                    del cache[key]
                    try:
                        order.remove(key)
                    except ValueError:
                        pass
            result = user_function(*args, **kwds)
            cache[key] = (result, now)
            order.append(key)
            if len(order) > maxsize:
                oldest = order.pop(0)
                del cache[oldest]
            return result
        return wrapper
    return decorating_function

