        """Define this to return the implementation in use,
        without the 'Py' or 'Fallback' suffix."""
        name = self.__class__.__name__
        if name.endswith('Py'):
            return name[:-2]
        if name.endswith('Fallback'):
            return name[:-8]
        return name

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    cls_name = self.__class__.__name__
    for suffix in ("Py", "Fallback"):
        if cls_name.endswith(suffix):
            cls_name = cls_name[:-len(suffix)]
            break
    module_name = self.__class__.__module__
    module = __import__(module_name, fromlist=[cls_name])
    return getattr(module, cls_name)

def directlyProvidedBy(object):
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # If `object` is a class, prefer its own declaration
    if isinstance(object, type):
        decl = getattr(object, "__providedBy__", None)
        if decl is not None:
            return decl
        decl = getattr(object, "__directlyProvided__", None)
        if decl is not None:
            return decl
        # No declaration found on the class; return an empty declaration
        return ()

    # `object` is an instance – check for an instance-level declaration
    decl = getattr(object, "__providedBy__", None)
    if decl is not None:
        return decl

    # Fall back to the class of the instance
    cls = type(object)
    decl = getattr(cls, "__providedBy__", None)
    if decl is not None:
        return decl
    decl = getattr(cls, "__directlyProvided__", None)
    if decl is not None:
        return decl

    # No declaration found at any level – return an empty declaration
    return ()

