    cls = object if isinstance(object, type) else getattr(object, "__class__", None)
    if cls is None:
        return InterfaceClass()
    return getattr(cls, "__provides__", InterfaceClass())

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Preserve the original order while eliminating any class that is an
    # ancestor of another class in the list.
    minimal = []
    # Precompute all relationships to avoid repeated issubclass checks.
    # ``is_ancestor`` maps a class to True if any other class in ``classes``
    # is subclass of it.
    ancestors = {cls: False for cls in classes}
    length = len(classes)
    for i in range(length):
        ci = classes[i]
        for j in range(length):
            if i == j:
                continue
            cj = classes[j]
            try:
                if issubclass(cj, ci) and ci is not cj:
                    ancestors[ci] = True
                    break
            except TypeError:
                # Skip non‑class objects or classes that don't support issubclass.
                continue
    for cls in classes:
        if not ancestors.get(cls, False):
            minimal.append(cls)
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        # Skip non-type objects
        if not isinstance(cls, type):
            continue
        # Remove any existing bases that are subclasses of the new one
        minimal = [m for m in minimal if not issubclass(m, cls) and m is not cls]
        # If the new class is already covered by an existing superclass, skip it
        if any(issubclass(cls, m) for m in minimal):
            continue
        # Avoid duplicates
        if cls not in minimal:
            minimal.append(cls)
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        # Skip this class if it is the superclass of any other class in the list.
        if any(issubclass(other, cls) and other is not cls for other in classes):
            continue
        minimal.append(cls)
    return minimal

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    import inspect

    # Collect attributes defined directly on the interface class
    members = {
        name: value
        for name, value in self.__class__.__dict__.items()
        if not inspect.isroutine(value) and not (name.startswith("__") and name.endswith("__"))
    }

    result = {}
    for name, value in members.items():
        if not all and name.startswith("_"):
            continue

        description = ""

        # Prefer a custom 'description' attribute if present
        if hasattr(value, "description"):
            description = value.description
        # Fallback to the docstring of the attribute itself
        if not description and hasattr(value, "__doc__"):
            doctxt = value.__doc__
            if doctxt:
                description = doctxt.strip().splitlines()[0]
        # For descriptors like property, try to get the docstring of the getter
        if not description and isinstance(value, property):
            if value.fget and value.fget.__doc__:
                description = value.fget.__doc__.strip().splitlines()[0]

        result[name] = description

    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    import inspect

    result = {}
    # Inspect class, including inherited members
    for name, value in inspect.getmembers(self.__class__):
        # Skip private attributes and magic methods
        if name.startswith('_'):
            continue
        # Skip callables
        if inspect.isroutine(value):
            continue

        description = ''

        # Special handling for properties
        if isinstance(value, property):
            fget = value.fget
            if fget and fget.__doc__:
                description = fget.__doc__.strip()
            elif value.__doc__:
                description = value.__doc__.strip()
        else:
            # For other attributes, try to get docstring if present
            doc = getattr(value, '__doc__', None)
            if isinstance(doc, str):
                description = doc.strip()

        # Include attribute if 'all' is True or a description exists
        if all or description:
            result[name] = description

    return result

