def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if all:
        # Include names from the class and its bases, excluding private names.
        collected = set()
        for cls in self.__class__.__mro__:
            collected.update(name for name in cls.__dict__ if not name.startswith("_"))
