def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect names from class attributes (excluding private and callables)
    attr_names = set()

    # Include attributes declared via annotations
    annotations = getattr(self.__class__, "__annotations__", {})
    attr_names.update(annotations.get(name, None) for name in annotations)

    # Walk the MRO to gather attributes from each class
    for cls in self.__class__.mro():
        for name, value in cls.__dict__.items():
            if name.startswith("_"):
                continue
            # Include properties as attributes
            if isinstance(value, property):
                attr_names.add(name)
            # Include regular data attributes
            elif not callable(value):
                attr_names.add(name)

    # When `all=True`, include instance-level attributes
    if all:
        for name in self.__dict__:
            if name.startswith("_"):
                continue
            attr_names.add(name)

    # Return sorted list of unique attribute names
    return sorted(attr_names)

