def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        # Prefer the library's own definition which handles all edge cases.
        return _use_c_impl()
    except NameError:
        # Fallback implementation if `_use_c_impl` is not available.
        import os, sys
        # Respect the PURE_PYTHON flag if set.
        if os.getenv('PURE_PYTHON') is not None:
            return False
        # Avoid C optimizations on PyPy as it may lack native extensions.
        if getattr(sys, 'pypy_version_info', None) is not None:
            return False
        # Default to attempting C optimizations on CPython.
        return True

