def to_csv(self, separator=",", header=None):
    """
    .. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    if header is not None:
        yield header
    for point in self:
        # Try to unpack a typical (coord, value) tuple
        if isinstance(point, (tuple, list)):
            try:
                coord, val = point
            except ValueError:
                coord, *rest = point
                val = rest[0] if rest else None
        else:
            coord, val = point, None

        parts = []
        # Handle coordinate part; may itself be a tuple/list
        if isinstance(coord, (tuple, list)):
            parts.extend(str(c) for c in coord)
        else:
            parts.append(str(coord))

        # Handle value part
        if val is not None:
            if isinstance(val, (tuple, list)):
                parts.extend(str(v) for v in val)
            else:
                parts.append(str(val))

        yield separator.join(parts)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Assuming `self._err_indices` is a dictionary mapping coordinate names to
    # arrays/lists of indices where errors were detected.  If the coordinate
    # is not present, return an empty list so callers can handle missing
    # data gracefully.
    if not hasattr(self, "_err_indices"):
        raise AttributeError("Attribute _err_indices not defined in this object")
    return self._err_indices.get(coord_name, [])

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Prefer the explicit mapping if it exists
    if hasattr(self, "_err_indices") and isinstance(self._err_indices, dict):
        return self._err_indices.get(coord_name, [])
    # Try to infer from an errors dictionary
    if hasattr(self, "errors") and isinstance(self.errors, dict):
        err_key = f"{coord_name}_err"
        if err_key in self.errors:
            err_obj = self.errors[err_key]
            # If it's a DataArray-like object with index mapping
            if hasattr(err_obj, "indexes") and coord_name in err_obj.indexes:
                return err_obj.indexes[coord_name]
            if hasattr(err_obj, "coords") and coord_name in err_obj.coords:
                return err_obj.coords[coord_name]
            # If it's a sequence, return the indices of non-None values
            try:
                return [i for i, v in enumerate(err_obj) if v is not None]
            except TypeError:
                pass
    # Default empty list if no appropriate mapping was found
    return []

def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        # Attempt to retrieve error indices from the class data structure.
        # 1. Look in self.Data dictionary if it exists.
        if hasattr(self, 'Data') and isinstance(self.Data, dict):
            entry = self.Data.get(coord_name, {})
            if isinstance(entry, dict):
                # Preferred key for error indices
                if 'error_indices' in entry:
                    return np.asarray(entry['error_indices'], dtype=int)
                # Fallback: boolean or integer error mask
                if 'error' in entry:
                    return np.where(np.asarray(entry['error']))[0]
        # 2. Look for a dedicated error mapping attribute
        if hasattr(self, 'err_by_coord'):
            indices = self.err_by_coord.get(coord_name)
            if indices is not None:
                return np.asarray(indices, dtype=int)
        # 3. If no known structure, return empty array
        return np.array([], dtype=int)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If it's a single FillRequest element
    if isinstance(seq, FillRequest):
        return True

    # If it's a Source sequence, we reject
    if isinstance(seq, Source):
        return False

    # If it's not iterable or is a string/bytes, cannot be
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    # Check each element
    for item in iterator:
        if isinstance(item, FillRequest):
            return True

    return False

