    and it is not a Source sequence.
    """
    # Do not accept Source sequences
    if isinstance(seq, SourceSequence):
        return False

    # Accept a single FillRequest element
    if isinstance(seq, FillRequest):
        return True

    # If seq is not iterable return False
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    # Check if any element is a FillRequest
    for element in iterator:
        if isinstance(element, FillRequest):
            return True

    return False

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if isinstance(seq, FillRequest):
        return True
    # Non-iterable or string-like objects should be rejected
    if not hasattr(seq, "__iter__") or isinstance(seq, (str, bytes)):
        return False
    # Reject Source sequences explicitly
    if isinstance(seq, Source):
        return False
    # Check if it contains at least one FillRequest element
    return any(isinstance(item, FillRequest) for item in seq)

