def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    import copy

    # Ensure level is either positive integer or -1 for infinite
    if level is not None and level < 0 and level != -1:
        raise ValueError("level must be -1 (infinite) or a non-negative integer")

    def _diff(a, b, lev):
        """Internal recursive helper."""
        out = {}
        for key, val_a in a.items():
            if key not in b:
                # Key only in d1 – include it
                out[key] = (
                    copy.deepcopy(val_a) if isinstance(val_a, dict) else val_a
                )
            else:
                val_b = b[key]
                # If both values are dicts and we have not exhausted recursion depth
                if isinstance(val_a, dict) and isinstance(val_b, dict):
                    # Determine next level
                    next_lev = lev
                    if lev != -1:
                        if lev <= 0:
                            # No more recursion; treat as difference if unequal
                            if val_a != val_b:
                                out[key] = copy.deepcopy(val_a)
                        else:
                            next_lev = lev - 1
                            sub = _diff(val_a, val_b, next_lev)
                            if sub:
                                out[key] = sub
                else:
                    # Non-dict values – include if they differ
                    if val_a != val_b:
                        out[key] = val_a
        return out

    return _diff(d1, d2, level) if isinstance(d1, dict) and isinstance(d2, dict) else {}

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dict")
    if not isinstance(d2, dict):
        raise TypeError("d2 must be a dict")
    result = {}
    for key, val in d1.items():
        if key not in d2:
            result[key] = val
        else:
            val2 = d2[key]
            if isinstance(val, dict) and isinstance(val2, dict):
                # determine recursion depth for child
                child_level = level - 1 if level > 0 else level
                subdiff = difference(val, val2, child_level)
                if subdiff:
                    result[key] = subdiff
            else:
                if val != val2:
                    result[key] = val
    return result

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # If no recursion allowed, return empty dict
    if level == 0:
        return {}

    diff = {}
    for key, val in d1.items():
        if key not in d2:
            # key missing in d2, include directly
            diff[key] = val
        else:
            val2 = d2[key]
            if isinstance(val, dict) and isinstance(val2, dict):
                # Both values are dicts, recurse if allowed
                if level == -1:
                    new_level = -1
                else:
                    new_level = level - 1
                subdiff = difference(val, val2, new_level)
                if subdiff:
                    # Include only non-empty subdiff
                    diff[key] = subdiff
            else:
                # Non-dict values: include if they differ
                if val != val2:
                    diff[key] = val
    return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    coord = np.asarray(coord)
    # If coord has more than one dimension, treat each row as a point
    if coord.ndim == 1:
        points = [coord]
    else:
        points = coord

    for pt in points:
        # build a list of bin indices for each dimension
        indices = []
        for dim, edge in enumerate(self.edges):
            # find the rightmost bin edge less than or equal to the coordinate
            i = np.searchsorted(edge, pt[dim], side='right') - 1
            # ignore points outside histogram range
            if i < 0 or i >= self.hist.shape[dim]:
                break
            indices.append(i)
        else:
            # only update if all dimensions are inside bounds
            self.hist[tuple(indices)] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str):
            errors.append({repr(key): "expected string or bytes-like object"})
        else:
            if not LABEL_KEY_RE.match(key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex [...]"}
                )

        # Validate value
        if isinstance(value, list):
            # The list itself is not an acceptable value type.
            errors.append(
                {repr(value): "expected string or bytes-like object"}
            )
            # Validate each element inside the list
            for elem in value:
                if not isinstance(elem, str):
                    errors.append(
                        {repr(elem): "expected string or bytes-like object"}
                    )
                else:
                    if not LABEL_VALUE_RE.match(elem):
                        errors.append(
                            {
                                repr(elem): f"Label value '{elem}' does not match the regex [...]"
                            }
                        )
        else:
            if not isinstance(value, str):
                errors.append(
                    {repr(value): "expected string or bytes-like object"}
                )
            else:
                if not LABEL_VALUE_RE.match(value):
                    errors.append(
                        {
                            repr(value): f"Label value '{value}' does not match the regex [...]"
                        }
                    )

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    # Regular expressions for valid keys and values.
    key_regex = r"^[a-zA-Z0-9_.-]+$"
    value_regex = r"^[a-zA-Z0-9_.-]+$"

    errors = []

    for key, value in labels.items():
        # Validate key type.
        if not isinstance(key, (str, bytes)):
            errors.append({repr(key): "expected string or bytes-like object"})
        else:
            try:
                # Ensure key is a string for regex matching.
                key_str = key.decode() if isinstance(key, bytes) else key
            except Exception:
                errors.append({repr(key): "expected string or bytes-like object"})
                key_str = None
            if key_str is not None:
                if not re.match(key_regex, key_str):
                    errors.append(
                        {key_str: f"Label key '{key_str}' does not match the regex [...]"}
                    )

        # Validate value type.
        if not isinstance(value, (str, bytes)):
            errors.append({repr(value): "expected string or bytes-like object"})
            continue
        else:
            try:
                value_str = value.decode() if isinstance(value, bytes) else value
            except Exception:
                errors.append({repr(value): "expected string or bytes-like object"})
                value_str = None
            if value_str is not None:
                if not re.match(value_regex, value_str):
                    errors.append(
                        {value_str: f"Label value '{value_str}' does not match the regex [...]"}
                    )

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
