            else:
                if not value_regex.match(v):
                    messages.append(
                        {v: f"Label value '{v}' does not match the regex [...]"})

    if messages:
        raise ValidationError(messages)#

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    The implementation assumes that *observer_schema* is an iterable of
    elements that either are dictionaries containing a ``name`` key and
    optionally a ``children`` key for nested structures, or are simple
    strings naming a field.  *response* is expected to be a mapping from
    field names to values.  *last_applied_manifest* may be a dictionary
    or a list; the function treats the two cases slightly differently but
    preserves the intended semantics of adding missing keys.

    Args:
        last_applied_manifest (list or dict):
            Partial ``last_applied_manifest`` being updated.
        observer_schema (list):
            Schema describing which fields to observe.
        response (dict):
            Partial response from the Kubernetes API.

    Returns:
        None: the function updates ``last_applied_manifest`` in place.
    """
    # Detect the type of ``last_applied_manifest``.
    is_dict_container = isinstance(last_applied_manifest, dict)

    for schema_item in observer_schema:
        # Handle dict-style schema entries.
        if isinstance(schema_item, dict):
            # The field name that we should look for.
            field_name = schema_item.get("name")
            if not field_name:
                continue

            # Extract the value from the response; default to ``None`` if not
            # present.
            value_in_resp = response.get(field_name)

            # If the field is missing from the current manifest, add it.
            if is_dict_container:
                if field_name not in last_applied_manifest:
                    last_applied_manifest[field_name] = value_in_resp
                    # Keep the key if the value is None, so that future code can
                    # distinguish a genuinely missing field from a field
                    # intentionally set to ``None``.
            else:
                # For a list container we append a dict entry.
                existing = next(
                    (e for e in last_applied_manifest if isinstance(e, dict)
                     and field_name in e),
                    None,
                )
                if existing is None:
                    last_applied_manifest.append(
                        {field_name: value_in_resp}
                    )

            # Recursively update nested structures if applicable.
            if (
                isinstance(value_in_resp, (dict, list))
                and "children" in schema_item
            ):
                # Ensure the nested container exists.
                nested_container = (
                    last_applied_manifest[field_name]
                    if is_dict_container
                    else next(
                        (e for e in last_applied_manifest if isinstance(e, dict)
                         and field_name in e),
                        None,
                    )[{field_name}]
                )
                if nested_container is None:
                    nested_container = {}
                    if is_dict_container:
                        last_applied_manifest[field_name] = nested_container
                    else:
                        # Replace the placeholder dict entry to hold children.
                        for i, e in enumerate(last_applied_manifest):
                            if isinstance(e, dict) and field_name in e:
                                last_applied_manifest[i] = {
                                    **e,
                                    field_name: nested_container,
                                }
                                break

                update_last_applied_manifest_list_from_resp(
                    nested_container,
                    schema_item.get("children", []),
                    value_in_resp,
                )
        # Handle simple string schema entries.
        elif isinstance(schema_item, str):
            field_name = schema_item
            if field_name not in response:
                continue
            value_in_resp = response[field_name]

            if is_dict_container:
                if field_name not in last_applied_manifest:
                    last_applied_manifest[field_name] = value_in_resp
            else:
                existing = next(
                    (e for e in last_applied_manifest if isinstance(e, dict)
                     and field_name in e),
                    None,
                )
                if existing is None:
                    last_applied_manifest.append({field_name: value_in_resp})

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Recursively populate *last_applied_manifest* with missing fields from
    a partial Kubernetes *response*, according to the *observer_schema*.

    Parameters
    ----------
    last_applied_manifest : dict
        The target manifest being updated. Keys that are not present in the
        ``response`` are set to the values found in ``response``.  Nested
        fields are handled recursively when a sub‑schema is supplied.

    observer_schema : list of dict or str
        Schema describing the fields that should be observed.  Each item
        is either a string containing the field name or a mapping
        containing:

            * ``name`` / ``field`` / ``key`` – the field name
            * ``schema`` – optional nested schema for nested objects/lists

    response : dict
        Partial response from the Kubernetes API from which the missing
        values are taken.

    Notes
    -----
    * The function updates ``last_applied_manifest`` in place.
    * For nested structures, it delegates to
      :func:`update_last_applied_manifest_dict_from_resp` which must
      exist in the same module.
    """
    for item in observer_schema:
        # Resolve field name.
        if isinstance(item, dict):
            field = item.get("name") or item.get("field") or item.get("key")
            sub_schema = item.get("schema")
        else:
            field = item
            sub_schema = None

        if not field:
            continue

        # Skip if field already exists or missing from response.
        if field in last_applied_manifest or not isinstance(
            response, (dict, list)
        ):
            continue

        try:
            val = response[field]
        except Exception:
            continue

        if sub_schema and isinstance(val, dict):
            # Nested dict – ensure a dict exists and recurse.
            if field not in last_applied_manifest or not isinstance(
                last_applied_manifest[field], dict
            ):
                last_applied_manifest[field] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], sub_schema, val
            )
        elif sub_schema and isinstance(val, list):
            # List of nested items – recurse on each dict item.
            last_applied_manifest[field] = []
            for itm in val:
                if isinstance(itm, dict):
                    nested = {}
                    update_last_applied_manifest_dict_from_resp(
                        nested, sub_schema, itm
                    )
                    last_applied_manifest[field].append(nested)
                else:
                    last_applied_manifest[field].append(itm)
        else:
            # Primitive value – set if missing.
            if field not in last_applied_manifest:
                last_applied_manifest[field] = val

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the manifest is available
    manifest = getattr(app.spec, 'manifest', [])
    # Initialise the dictionary that will hold observer schemas if it does not exist
    if not hasattr(app.spec, 'observer_schema'):
        app.spec.observer_schema = {}
    # Iterate over all resources defined in the manifest
    for resource in manifest:
        kind = resource.get('kind')
        metadata = resource.get('metadata', {})
        namespace = metadata.get('namespace', 'default')
        name = metadata.get('name')
        # Create a unique key that identifies a resource instance
        key = f"{kind}/{namespace}/{name}"
        # Skip if a custom schema already exists for this resource
        if key in app.spec.observer_schema:
            continue
        # Default observer schema: a generic object with standard Kubernetes fields
        default_schema = {
            "type": "object",
            "properties": {
                "metadata": {"type": "object"},
                "spec": {"type": "object"},
                "status": {"type": "object"}
            }
        }
        # Store the default schema under the generated key
        app.spec.observer_schema[key] = default_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application has an observer_schema attribute
    if not hasattr(app.spec, 'observer_schema') or app.spec.observer_schema is None:
        app.spec.observer_schema = {}

    # Build a set of already defined observer schemas for quick lookup
    defined_keys = set(app.spec.observer_schema.keys())

    # Iterate over the Kubernetes resources specified in the application manifest
    manifest = getattr(app.spec, 'manifest', [])
    for resource in manifest:
        if not isinstance(resource, dict):
            continue  # skip non‑dict entries

        api_version = resource.get('apiVersion', '')
        kind = resource.get('kind', '')
        if not api_version or not kind:
            continue  # skip malformed entries

        key = f"{api_version}/{kind}"
        if key in defined_keys:
            continue  # custom schema already provided

        # Construct a minimal default schema for the resource
        default_schema = {
            "type": "object",
            "properties": {
                "metadata": {
                    "type": "object",
                    "properties": {
                        "name": {"type": "string"},
                        "namespace": {"type": "string"},
                        "labels": {"type": "object"},
                        "annotations": {"type": "object"},
                    },
                    "required": ["name"],
                },
                "spec": {"type": "object"},
                "status": {"type": "object"},
            },
            "required": ["metadata"],
        }

        app.spec.observer_schema[key] = default_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Get the list of resources defined in the application spec
    manifest = getattr(app.spec, "manifest", [])
    # Get the list of observer schemas already defined
    observers = getattr(app.spec, "observers", [])
    # Build a set of observer kinds that already have schemas
    existing_kinds = {obs.get("kind") for obs in observers if isinstance(obs, dict)}
    # Iterate over each resource in the manifest
    for resource in manifest:
        kind = resource.get("kind")
        # Skip resources that do not have a kind or that already have
        # a default/custom observer schema
        if not kind or kind in existing_kinds:
            continue
        # Metadata for the new default observer schema
        meta = resource.get("metadata", {})
        # Build a minimal default observer schema
        default_schema = {
            "kind": kind,
            "metadata": {
                "namespace": meta.get("namespace", "default"),
                "name": meta.get("name", f"{kind.lower()}-default"),
            },
            "spec": {
                # Reference to the original resource
                "source": {
                    "apiVersion": resource.get("apiVersion"),
                    "kind": kind,
                    "metadata": {
                        "name": meta.get("name"),
                        "namespace": meta.get("namespace"),
                    },
                },
                # Default observation configuration
                "observe": {
                    "all": True
                },
            },
        }
        # Append the new default schema to the observer list
        observers.append(default_schema)
    # Make sure the updated observer list is stored back in the spec
    app.spec.observers = observers

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Retrieve the namespace or top-level spec attributes
    manifest = getattr(app.spec, "manifest", [])
    observers = getattr(app.spec, "observers", {})
    # Ensure observers is a dictionary
    if observers is None:
        observers = {}
    # Iterate over each resource in the manifest
    for res in manifest:
        if not isinstance(res, dict):
            # Skip if the resource entry is not a dict
            continue
        kind = res.get("kind")
        metadata = res.get("metadata", {})
        name = metadata.get("name")
        # Skip if required fields are missing
        if not kind or not name:
            continue
        # Use a unique key to identify the resource
        key = f"{kind}/{name}"
        if key not in observers:
            # Build a very simple default observer schema
            default_schema = {
                "kind": "Observer",
                "metadata": {
                    "name": f"{name}-observer",
                    "labels": {"app.kubernetes.io/owner": app.spec.name}
                },
                "spec": {
                    "resource": {"kind": kind, "name": name},
                    "enabled": True,
                },
            }
            observers[key] = default_schema
    # Record the updated observers mapping back into the application spec
    app.spec.observers = observers
    return

