def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Ensure the inputs are iterable
    if manifest_files is None:
        raise ValueError("manifest_files cannot be None")
    if digests_used is None:
        raise ValueError("digests_used cannot be None")

    # Normalise digests_used to a set for efficient lookup
    used_set = set(digests_used)

    # Extract digests from the manifest files
    manifest_digests = set()
    for entry in manifest_files:
        # Handle dictionary-like entries
        if isinstance(entry, dict):
            digest = entry.get('digest') or entry.get('sha256')
        else:
            # Try to access typical attributes
            digest = getattr(entry, 'digest', None) or getattr(entry, 'sha256', None)
        if digest:
            manifest_digests.add(digest)

    # Check that every digest required by the manifest is in the used set
    missing_in_used = manifest_digests - used_set
    if missing_in_used:
        missing_list = ', '.join(missing_in_used)
        raise ValueError(f"Digests required by manifest but not used: {missing_list}")

    # Check that every used digest is actually present in the manifest
    missing_in_manifest = used_set - manifest_digests
    if missing_in_manifest:
        missing_list = ', '.join(missing_in_manifest)
        raise ValueError(f"Digests used but not present in manifest: {missing_list}")

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same validation type
    if not isinstance(prior, type(self)):
        raise TypeError(f'prior must be an {type(self).__name__} instance, got {type(prior).__name__}')

    # Compare basic inventory identifiers if available
    try:
        self_id = self.inventory.id
        prior_id = prior.inventory.id
        if self_id != prior_id:
            raise ValueError(f'Inventory IDs do not match: {self_id!r} vs {prior_id!r}')
    except AttributeError:
        # If no explicit id, fall back to comparing inventory objects directly
        if getattr(self, 'inventory', None) != getattr(prior, 'inventory', None):
            raise ValueError('Inventories do not match between current and prior objects')

    # Ensure version ordering (assume a numeric or comparable version attribute)
    try:
        if getattr(self, 'version', 0) <= getattr(prior, 'version', 0):
            raise ValueError(f'Current version ({getattr(self, "version", None)}) must be greater than prior version ({getattr(prior, "version", None)})')
    except AttributeError:
        # If no version attribute, the validation cannot be performed
        pass

    # Verify that all entries present in the prior inventory are also present in the current one
    try:
        prior_keys = set(prior.inventory.keys())
        current_keys = set(self.inventory.keys())
        missing = prior_keys - current_keys
        if missing:
            raise ValueError(f'Current inventory is missing keys from prior inventory: {sorted(missing)!r}')
    except AttributeError:
        # If inventory does not support keys(), skip this check
        pass

    # All checks passed
    return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.
    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the expected type
    if not isinstance(prior, InventoryValidator):
        raise TypeError(
            f"prior must be an InventoryValidator instance, got {type(prior).__name__}"
        )

    # Basic version ordering check – prior should be older than current
    if hasattr(self, "version") and hasattr(prior, "version"):
        if prior.version >= self.version:
            raise ValueError(
                f"Prior version ({prior.version}) must be less than current "
                f"version ({self.version})"
            )
    else:
        raise AttributeError(
            "Both self and prior must have a 'version' attribute to perform "
            "prior validation."
        )

    # Ensure that the species sets are compatible
    if hasattr(self, "species") and hasattr(prior, "species"):
        current_species = set(self.species)
        prior_species = set(prior.species)
        # Species count should match
        if len(current_species) != len(prior_species):
            raise ValueError(
                f"Species count mismatch: current has {len(current_species)} "
                f"while prior has {len(prior_species)}"
            )
        # Every species in the prior must be present in the current inventory
        missing = prior_species - current_species
        if missing:
            raise ValueError(
                f"The following species in the prior are not present in the "
                f"current inventory: {sorted(missing)}"
            )
    else:
        raise AttributeError(
            "Both self and prior must have a 'species' attribute to perform "
            "prior validation."
        )

    # Ensure that constraints (if any) are preserved
    if hasattr(self, "constraints") and hasattr(prior, "constraints"):
        # For simplicity, just check that all constraint keys match
        current_c = set(self.constraints.keys())
        prior_c = set(prior.constraints.keys())
        if current_c != prior_c:
            raise ValueError(
                f"Constraint keys differ between current ({sorted(current_c)}) "
                f"and prior ({sorted(prior_c)}) inventories."
            )
    # If all checks pass, the prior is considered valid
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    from collections import defaultdict

    # Helper to parse and compare version strings
    try:
        from distutils.version import LooseVersion
        def v_key(v):
            return LooseVersion(v)
    except Exception:
        def v_key(v):
            return v

    mapping = defaultdict(set)

    # Helper to extract attributes from a record
    def _get(rec, attr):
        if isinstance(rec, dict):
            return rec.get(attr)
        return getattr(rec, attr, None)

    # Case 1: inventory is a dict where keys are logical paths
    if isinstance(inventory, dict):
        # Check if values appear to be version maps or direct file sets
        val0 = next(iter(inventory.values()), None)
        if isinstance(val0, dict):
            # mapping: logical_path -> {version: set(files)}
            for logical_path, ver_map in inventory.items():
                files = ver_map.get(version, set())
                mapping[logical_path].update(files)
            # Include duplicates from later versions
            for logical_path, ver_map in inventory.items():
                for ver, files in ver_map.items():
                    try:
                        if v_key(ver) > v_key(version):
                            if logical_path in mapping:
                                mapping[logical_path].update(files)
                    except Exception:
                        continue
            return dict(mapping)

        # Check if values are file sets for this version
        if isinstance(val0, (set, list, tuple)):
            for logical_path, files in inventory.items():
                mapping[logical_path].update(files)
            return dict(mapping)

        # Handle nested dicts that might map to different attribute fields
        for logical_path, val in inventory.items():
            if isinstance(val, dict):
                files = val.get(version, set())
                if isinstance(files, (set, list, tuple)):
                    mapping[logical_path].update(files)
        return dict(mapping)

    # Case 2: inventory is an iterable of records (dict or object)
    # Build mapping for the exact version first
    for rec in inventory:
        rec_ver = _get(rec, 'version')
        logical_path = _get(rec, 'logical_path')
        content_file = _get(rec, 'content_file')
        if rec_ver is None or logical_path is None or content_file is None:
            continue
        if rec_ver == version:
            mapping[logical_path].add(content_file)

    # Include duplicates from later versions for the same logical paths
    for rec in inventory:
        rec_ver = _get(rec, 'version')
        logical_path = _get(rec, 'logical_path')
        content_file = _get(rec, 'content_file')
        if rec_ver is None or logical_path is None or content_file is None:
            continue
        try:
            if v_key(rec_ver) > v_key(version) and logical_path in mapping:
                mapping[logical_path].add(content_file)
        except Exception:
            pass

    return dict(mapping)

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_map = {}
    for ver, state in inventory.items():
        if ver != version:
            continue
        for logical_path, files in state.items():
            logical_map.setdefault(logical_path, set()).update(files)
    return logical_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # If inventory is empty or None, return an empty mapping
    if not inventory:
        return {}

    # Sort the version keys in a deterministic order.  We assume the keys are
    # comparable as strings; if more complex ordering is required, this
    # logic can be replaced with a custom key function.
    sorted_versions = sorted(inventory.keys(), key=lambda v: str(v))

    # Find the index of the requested version.  If it is not present, return
    # an empty result.
    try:
        start_index = sorted_versions.index(version)
    except ValueError:
        return {}

    # Aggregate the content files for the requested version and all later
    # versions.
    result = {}
    for v in sorted_versions[start_index:]:
        mapping = inventory.get(v, {})
        # The mapping for a given version is expected to be a dictionary
        # mapping logical paths to content file paths.
        for logical_path, content_file in mapping.items():
            result.setdefault(logical_path, set()).add(content_file)

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    def _parse_version(v):
        """Parse a version string into a tuple of comparable elements."""
        parts = []
        for part in v.replace("-", ".").split("."):
            try:
                parts.append(int(part))
            except ValueError:
                parts.append(part)
        return tuple(parts)

    target_ver = _parse_version(version)
    logical_map = {}

    for logical_path, ver_map in inventory.items():
        content_files = set()
        for ver, files in ver_map.items():
            if _parse_version(ver) >= target_ver:
                if isinstance(files, (set, list)):
                    content_files.update(files)
                else:
                    content_files.add(files)
        if content_files:
            logical_map[logical_path] = content_files

    return logical_map

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Ensure fixity is a dictionary
        if not isinstance(fixity, dict):
            raise ValueError('Fixity block must be a dictionary')

        # The expected key holding file entries
        if 'files' not in fixity:
            raise ValueError('Missing required "files" key in fixity block')

        files = fixity['files']
        if not isinstance(files, list):
            raise ValueError('"files" must be a list of file entries')

        # Convert manifest files into a set of valid paths
        manifest_set = set(manifest_files)

        seen_paths = set()
        for idx, entry in enumerate(files):
            if not isinstance(entry, dict):
                raise ValueError(f'File entry #{idx} must be a dictionary')

            if 'path' not in entry:
                raise ValueError(f'Missing "path" in file entry #{idx}')

            path = entry['path']
            if path not in manifest_set:
                raise ValueError(f'File "{path}" in fixity not found in manifest')

            if path in seen_paths:
                raise ValueError(f'Duplicate reference to file "{path}" in fixity')
            seen_paths.add(path)

            # Optional: basic validation of hash and algorithm fields
            if 'hash' not in entry or not isinstance(entry['hash'], str) or not entry['hash']:
                raise ValueError(f'Invalid or missing "hash" for file "{path}"')

            if 'algorithm' in entry and not isinstance(entry['algorithm'], str):
                raise ValueError(f'Invalid "algorithm" for file "{path}"')

        return True

