def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Require 'type' and 'files' keys
    if 'type' not in fixity:
        raise ValueError("Fixity block missing required key 'type'")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing required key 'files'")

    # Validate 'type' value
    if not isinstance(fixity['type'], str):
        raise ValueError("Fixity 'type' must be a string")

    # Validate 'files' mapping
    files = fixity['files']
    if not isinstance(files, dict):
        raise ValueError("Fixity 'files' must be a dictionary mapping file names to checksums")

    # Ensure all referenced files are present in the manifest
    missing_from_manifest = []
    invalid_checksum_types = []

    for path, checksum in files.items():
        if path not in manifest_files:
            missing_from_manifest.append(path)

        if not isinstance(checksum, str):
            invalid_checksum_types.append((path, type(checksum).__name__))

    if missing_from_manifest:
        raise ValueError(f"Fixity references unknown files: {', '.join(missing_from_manifest)}")

    if invalid_checksum_types:
        details = ", ".join(f"{p} ({t})" for p, t in invalid_checksum_types)
        raise ValueError(f"Invalid checksum types for {details}")

    # If needed, additional integrity checks (e.g., proper hash format) can be added here
    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure that the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Required keys in a fixity block
    required_keys = {"filename", "hash"}
    missing_keys = required_keys - set(fixity.keys())
    if missing_keys:
        raise ValueError(f"Missing keys in fixity block: {', '.join(sorted(missing_keys))}")

    # Validate filename
    filename = fixity["filename"]
    if not isinstance(filename, str) or not filename:
        raise ValueError("Filename in fixity block must be a non-empty string")

    # Ensure the referenced file is present in the manifest
    if filename not in manifest_files:
        raise ValueError(f"Fixity block references unknown file '{filename}'")

    # Validate hash value (should be a hexadecimal string)
    hash_value = fixity["hash"]
    if not isinstance(hash_value, str) or not hash_value.strip():
        raise ValueError("Hash value must be a non-empty string")
    if any(c not in "0123456789abcdefABCDEF" for c in hash_value.strip()):
        raise ValueError("Hash value contains non-hexadecimal characters")

    # Optional: if an algorithm key is present, ensure it is supported
    if "algorithm" in fixity:
        algo = fixity["algorithm"]
        if not isinstance(algo, str) or algo not in {"md5", "sha1", "sha256", "sha512"}:
            raise ValueError(f"Unsupported hash algorithm '{algo}'")

