def add_rendition(self, lang, file_path):
        """
        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }
        """
        # Ensure the renditions dictionary exists
        if not hasattr(self, 'renditions'):
            self.renditions = {}

        # Extract the filename from the provided path
        base_name = os.path.basename(file_path)

        if lang == 'original':
            # Store only the original rendition
            self.renditions[base_name] = {'original': base_name}
            return self.renditions

        # Assume the file_name follows the pattern: <something>-<lang>.ext
        name, ext = os.path.splitext(base_name)
        parts = name.rsplit('-', 1)
        if len(parts) == 2 and parts[1] == lang:
            original_name = parts[0] + ext
        else:
            # Fallback: use the provided base_name as original
            original_name = base_name

        # Ensure the original entry exists
        if original_name not in self.renditions:
            self.renditions[original_name] = {'original': original_name}

        # Add or update the language-specific rendition
        self.renditions[original_name][lang] = base_name
        return self.renditions

def add_rendition(self, lang, file_path):
    """
    Adds a language-specific rendition of the original file path.

    Example mapping:
        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }

    Args:
        lang (str): Language code for the rendition (e.g., 'en', 'es').
        file_path (str): Path to the rendition file.

    Raises:
        TypeError: If `lang` or `file_path` is not a string.
        ValueError: If either argument is an empty string.

    Returns:
        bool: True if the rendition was added successfully.
    """
    if not isinstance(lang, str):
        raise TypeError(f"Expected `lang` to be a str, got {type(lang).__name__}")
    if not isinstance(file_path, str):
        raise TypeError(f"Expected `file_path` to be a str, got {type(file_path).__name__}")

    if not lang:
        raise ValueError("`lang` cannot be an empty string")
    if not file_path:
        raise ValueError("`file_path` cannot be an empty string")

    if not hasattr(self, "_renditions") or not isinstance(self._renditions, dict):
        self._renditions = {}

    self._renditions[lang] = file_path
    return True

