def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile, os

    packages = {}
    with zipfile.ZipFile(zip_path, 'r') as zf:
        for info in zf.infolist():
            if info.is_dir():
                continue
            file_path = info.filename
            content = zf.read(info)
            base_name, ext = os.path.splitext(os.path.basename(file_path))
            # Only files that share the same xml base name are grouped together
            # The xml file itself will be the top-level key for the group
            if ext.lower() == ".xml":
                packages[base_name] = {file_path: content}
            else:
                # Attempt to find the xml file that should belong to this file
                for xml_candidate in packages.keys():
                    # If the file shares the same parent directory as the xml
                    xml_dir = os.path.dirname(
                        [p for p in packages[xml_candidate].keys() if p.endswith('.xml')][0]
                    )
                    if os.path.commonpath([xml_dir, file_path]) == xml_dir:
                        packages[xml_candidate][file_path] = content
                        break
                else:
                    # If no matching xml is found, use its own basename as a key
                    if base_name not in packages:
                        packages[base_name] = {}
                    packages[base_name][file_path] = content
    return packages

