def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        import pprint
    except Exception:
        return str(self)

    if debug:
        # Show attributes of the object with detailed formatting
        attrs = getattr(self, '__dict__', None)
        if attrs is None:
            return str(self)
        lines = []
        for name, value in sorted(attrs.items()):
            try:
                val_str = pprint.pformat(value, indent=indent, width=80)
            except Exception:
                val_str = repr(value)
            lines.append(' ' * indent + f'{name}={val_str}')
        body = "\n".join(lines)
        return f'{self.__class__.__name__}(\n{body}\n)'
    else:
        return pprint.pformat(self, indent=indent, width=80)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    header = f"{self.__class__.__name__}("
    lines = []
    for name, value in self.__dict__.items():
        # If the value has its own pretty method, use it
        if hasattr(value, "pretty") and callable(value.pretty):
            try:
                val_str = value.pretty(indent + 4, debug=False)
            except Exception:
                val_str = repr(value)
        else:
            val_str = repr(value)
        lines.append(f"{indent_str}  {name} = {val_str}")
    if lines:
        body = "\n".join(lines)
    else:
        body = f"{indent_str}  <no attributes>"
    footer = f"{indent_str})"
    return f"{header}\n{body}\n{footer}"

