def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate input type
    if not hasattr(pieces, '__iter__'):
        raise TypeError("pieces must be an iterable")

    pieces = list(pieces)

    if style == 'plain':
        # Simple space separated string
        return ' '.join(map(str, pieces))

    elif style == 'semver':
        # Build a semantic version string from the first three pieces
        try:
            major, minor, patch = pieces[:3]
            return f"{major}.{minor}.{patch}"
        except Exception:
            # Fallback to string representation if not enough pieces
            return str(pieces)

    elif style == 'html':
        # Wrap each piece in a list item within an unordered list
        return '<ul>' + ''.join(f"<li>{piece}</li>" for piece in pieces) + '</ul>'

    elif style == 'json':
        # Basic JSON formatting without external imports
        return '[' + ', '.join(repr(piece) for piece in pieces) + ']'

    else:
        raise ValueError(f"Unsupported style: {style!r}")

