def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    if args:
        cmd.extend(args)
    if verbose:
        print(f"Running command: {' '.join(cmd)}")
    # If hide_stderr is True we redirect stderr to stdout, otherwise let it pass through
    stderr_pipe = subprocess.PIPE if hide_stderr else None
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_pipe,
            env=env,
            check=True,
            text=True
        )
        return result.stdout
    except subprocess.CalledProcessError as exc:
        error_msg = f"Command '{' '.join(cmd)}' returned non‑zero exit status {exc.returncode}"
        if exc.stderr:
            error_msg += f"\nError output: {exc.stderr}"
        raise subprocess.CalledProcessError(exc.returncode, exc.cmd, output=exc.stdout, stderr=exc.stderr) from None

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    if args:
        if isinstance(args, (list, tuple)):
            cmd += list(args)
        else:
            cmd.append(str(args))
    if verbose:
        print('Running command:', ' '.join(map(str, cmd)))
    # Set up stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    try:
        process = subprocess.Popen(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True
        )
        stdout, stderr = process.communicate()
        if process.returncode != 0:
            err_msg = f"Command {' '.join(map(str, cmd))} failed with exit code {process.returncode}"
            if not hide_stderr and stderr:
                err_msg += f"; stderr: {stderr.strip()}"
            raise RuntimeError(err_msg)
        if verbose:
            print(stdout)
        return stdout.strip()
    except OSError as e:
        raise RuntimeError(f"Failed to execute command {' '.join(map(str, cmd))}: {e}") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        cmd = [commands] + (args or [])
    else:
        cmd = list(commands)
        if args:
            cmd.extend(args)

    # Verbose output
    if verbose:
        print("Running command:", " ".join(cmd))

    # Handle stderr suppression if requested
    stderr = subprocess.DEVNULL if hide_stderr else None

    try:
        # Run the command and capture its output
        output = subprocess.check_output(cmd, cwd=cwd, env=env,
                                         stderr=stderr, text=True)
    except subprocess.CalledProcessError as e:
        # Raise a RuntimeError with useful information
        raise RuntimeError(f"Command {' '.join(cmd)} failed with exit code {e.returncode}")

    return output

