def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import hashlib

    # Determine the root directory to walk; assume it is stored in self.storage_root or self.root
    root = getattr(self, 'storage_root', None) or getattr(self, 'root', None)
    if not root or not isinstance(root, str):
        if show_warnings:
            print("Storage root not defined or is not a string.")
        return 0, 0

    num_objects = 0
    good_objects = 0

    for dirpath, dirnames, filenames in os.walk(root):
        for filename in filenames:
            num_objects += 1
            file_path = os.path.join(dirpath, filename)
            is_valid = True

            # Validate the object itself (e.g., file exists and is readable)
            if validate_objects:
                try:
                    with open(file_path, 'rb') as f:
                        data = f.read()
                    if not data:
                        is_valid = False
                        if show_warnings:
                            print(f"Empty file detected: {file_path}")
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Could not read file {file_path}: {exc}")

            # Check digest if requested
            if is_valid and check_digests:
                digest_file = f"{file_path}.md5"
                if os.path.exists(digest_file):
                    try:
                        with open(digest_file, 'r') as df:
                            expected_digest = df.read().strip()
                        with open(file_path, 'rb') as f:
                            actual_digest = hashlib.md5(f.read()).hexdigest()
                        if actual_digest != expected_digest:
                            is_valid = False
                            if show_warnings:
                                print(f"Digest mismatch for {file_path}")
                    except Exception as exc:
                        is_valid = False
                        if show_warnings:
                            print(f"Error validating digest for {file_path}: {exc}")

            if is_valid:
                good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        # Expected that the hierarchy is stored as an iterable of objects
        # in an attribute named `_objects` or similar.  Fall back to empty list.
        objects = getattr(self, "_objects", [])
        if not hasattr(objects, "__iter__"):
            objects = [objects]

        for obj in objects:
            num_objects += 1
            is_valid = True

            # Optional per‑object validation
            if validate_objects:
                try:
                    if hasattr(obj, "validate"):
                        is_valid = bool(obj.validate())
                    elif hasattr(obj, "is_valid"):
                        is_valid = bool(obj.is_valid())
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"[WARN] Validation error for {obj}: {exc}")

            # Optional digest check
            if check_digests and is_valid:
                try:
                    if hasattr(obj, "check_digest"):
                        is_valid = bool(obj.check_digest())
                    elif hasattr(obj, "digests_valid"):
                        is_valid = bool(obj.digests_valid())
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"[WARN] Digest check failed for {obj}: {exc}")

            if is_valid:
                good_objects += 1
            elif show_warnings:
                print(f"[WARN] Object {obj} failed validation checks.")

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    warnings = []

    # Iterate over all objects in the hierarchy. It is assumed that the owning class
    # implements a method `_enumerate_objects` that yields every object instance
    # within the storage root.
    for obj in self._enumerate_objects():
        num_objects += 1
        is_valid = True

        if validate_objects:
            try:
                obj.validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    warnings.append(f"Object {obj} validation failed: {exc}")

        if check_digests and is_valid:
            try:
                if not obj.check_digest():
                    is_valid = False
                    if show_warnings:
                        warnings.append(f"Object {obj} digest mismatch")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    warnings.append(f"Object {obj} digest check failed: {exc}")

        if is_valid:
            good_objects += 1

    if show_warnings:
        for w in warnings:
            print(f"WARNING: {w}")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Attempt to retrieve hierarchy objects from common attributes
    objects = None
    for attr in ('hierarchy_objects', 'objects', 'all_objects'):
        if hasattr(self, attr):
            objects = getattr(self, attr)
            break

    # If still none, try a method that yields objects
    if objects is None:
        try:
            objects = list(self._iter_hierarchy())
        except Exception:
            objects = []

    for obj in objects:
        num_objects += 1
        is_good = True

        if validate_objects:
            try:
                is_good = bool(obj.is_valid())
            except Exception as exc:
                if show_warnings:
                    print(f"[validate_hierarchy] Validation error for {obj!r}: {exc}")
                is_good = False

        if check_digests and is_good:
            try:
                stored = getattr(obj, 'digest', None) or getattr(obj, 'stored_digest', None)
                computed_func = getattr(obj, 'compute_digest', None) or getattr(obj, 'calculate_digest', None)
                if computed_func and callable(computed_func):
                    computed = computed_func()
                else:
                    computed = None
                if stored is not None and computed is not None and stored != computed:
                    if show_warnings:
                        print(f"[validate_hierarchy] Digest mismatch for {obj!r}")
                    is_good = False
            except Exception as exc:
                if show_warnings:
                    print(f"[validate_hierarchy] Digest check failed for {obj!r}: {exc}")
                is_good = False

        if is_good:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    root_path = getattr(self, "root_path", None)
    if root_path is None:
        raise AttributeError("Instance must have a 'root_path' attribute.")
    if os.path.isdir(root_path):
        raise FileExistsError(f"OCFL root '{root_path}' already exists.")
    try:
        os.makedirs(root_path, exist_ok=False)
        ocfl_dir = os.path.join(root_path, ".ocfl_root")
        os.makedirs(ocfl_dir)
        # Create empty manifest and states files
        for fname in ("manifest.sha512", "states.lst"):
            with open(os.path.join(ocfl_dir, fname), "w"):
                pass
        # Write a minimal described.json file
        described = {
            "ocfl_version": "1.0",
            "created_at": datetime.utcnow().isoformat() + "Z",
            "root_path": root_path,
        }
        with open(os.path.join(ocfl_dir, "described.json"), "w") as f:
            f.write(json.dumps(described, indent=2))
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize OCFL root at {root_path}: {exc}") from exc

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ''
    parts = version.split('.')
    widths = [len(p) for p in parts]
    try:
        nums = [int(p) for p in parts]
    except ValueError:
        # If any part is not purely numeric, return the original version unchanged
        return version
    # Increment the last part
    nums[-1] += 1
    formatted = []
    for num, width, orig in zip(nums, widths, parts):
        if orig.startswith('0') and width > 1:
            formatted.append(str(num).zfill(width))
        else:
            formatted.append(str(num))
    return '.'.join(formatted)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""

    parts = version.strip().split('.')
    if not parts:
        return version.strip()

    last = parts[-1]
    # Determine if last part is numeric
    if not last.isdigit():
        return version.strip()

    # Compute next numeric value
    num = int(last)
    num += 1

    orig_len = len(last)
    new_last = str(num)

    # Preserve leading zeros if resulting number fits in original width
    if len(new_last) < orig_len:
        new_last = new_last.zfill(orig_len)

    parts[-1] = new_last
    return '.'.join(parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return ""

    parts = version.split(".")
    if not parts:
        return version

    # Process the last part; leading zeros should be preserved
    last = parts[-1]
    # try to interpret as integer even if it contains non-digit characters
    try:
        num = int(last)
    except ValueError:
        # If it cannot be parsed as a number, return original
        return version

    width = len(last) if last.isdigit() else 0

    # Increment the number
    num += 1

    if width > 0:
        new_last = str(num).zfill(width)
    else:
        new_last = str(num)

    parts[-1] = new_last
    return ".".join(parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    parts = version.split(".")
    if not parts:
        return version
    # Process the last numeric segment
    last = parts[-1]
    # Try to convert to integer
    try:
        num = int(last)
    except ValueError:
        # If the last part is not purely numeric, leave unchanged
        return version
    # Increment
    new_num = num + 1
    # Preserve leading zeros if present
    if len(last) > len(str(num)):
        new_last = str(new_num).zfill(len(last))
    else:
        new_last = str(new_num)
    parts[-1] = new_last
    return ".".join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure the root inventory has been loaded
    if not hasattr(self, "root_inventory") or self.root_inventory is None:
        raise RuntimeError("Root inventory has not been initialized.")
    root_inv = self.root_inventory

    # Record mismatches: {file_path: [(version_dir, digest), ...]}
    mismatches = {}

    for ver_dir in version_dirs:
        inventory_path = os.path.join(ver_dir, getattr(self, "inventory_file", "inventory.json"))
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file not found in: {ver_dir}")

        with open(inventory_path, "r") as f:
            try:
                inv = json.load(f)
            except Exception as e:
                raise ValueError(f"Failed to parse inventory at {inventory_path}: {e}")

        for path, digest in inv.items():
            if path not in root_inv:
                raise ValueError(
                    f"File {path!r} appears in inventory of {ver_dir!r} "
                    f"but does not exist in the root inventory."
                )
            if root_inv[path] != digest:
                mismatches.setdefault(path, []).append((ver_dir, digest))

    # Store mismatches for later validation checks
    self.mismatched_digests = mismatches
    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    # Record discrepancies between version inventories and the root inventory
    self.discrepancies = {}

    # Load the root inventory if it exists
    root_inventory = {}
    root_inventory_path = os.path.join(self.root_dir, "inventory.json")
    if os.path.isfile(root_inventory_path):
        with open(root_inventory_path, "r", encoding="utf-8") as fh:
            try:
                root_inventory = json.load(fh)
            except Exception:
                root_inventory = {}

    # Keep track of all seen files and their digests
    seen = {}

    for idx, vdir in enumerate(version_dirs, start=1):
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file: {inv_path}")

        with open(inv_path, "r", encoding="utf-8") as fh:
            try:
                inventory = json.load(fh)
            except Exception:
                raise ValueError(f"Inventory file is not valid JSON: {inv_path}")

        # Inventory should be a mapping of file_path to digest
        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory format unexpected in {inv_path}")

        # 1. Verify cumulative requirement
        for path, digest in inventory.items():
            if path in seen and seen[path] != digest:
                raise ValueError(
                    f"Digest for {path} in {vdir} differs from previous "
                    f"version (expected {seen[path]}, got {digest})"
                )
            seen[path] = digest

        # All previously seen files must exist in the current inventory
        missing = set(seen.keys()) - set(inventory.keys())
        if missing:
            raise ValueError(
                f"Inventory in {vdir} is missing files from earlier "
                f"versions: {sorted(missing)}"
            )

        # 2. Record any digest differences from the root inventory
        for path, digest in inventory.items():
            root_digest = root_inventory.get(path)
            if root_digest is None or root_digest != digest:
                self.discrepancies.setdefault(path, []).append(
                    {"version": idx, "digest": digest, "root_digest": root_digest}
                )

    return self

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    if not os.path.exists(path):
        return f"path does not exist: {path}"
    if os.path.isfile(path):
        return "file"
    if os.path.isdir(path):
        try:
            for entry in os.listdir(path):
                if entry.startswith("0="):
                    return "object"
            return "root"
        except Exception as exc:
            return f"error accessing directory: {exc}"
    return f"unknown path type: {path}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=* Namaste files" to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return f"does not exist: {path}"
    if os.path.isfile(path):
        return 'file'
    if os.path.isdir(path):
        # First, check for a storage root by looking for an "objects" subdirectory
        if os.path.isdir(os.path.join(path, 'objects')):
            return 'root'
        # Next, check if this directory looks like an OCFL object.
        # An object directory contains at least one subdirectory that
        # contains a file starting with "0." (e.g., "0.json", "0.namaste").
        try:
            dirs = os.listdir(path)
        except Exception as exc:
            return f"cannot list dir: {exc}"
        for d in dirs:
            subdir = os.path.join(path, d)
            if not os.path.isdir(subdir):
                continue
            try:
                items = os.listdir(subdir)
            except Exception:
                continue
            for item in items:
                if item.startswith('0.') and os.path.isfile(os.path.join(subdir, item)):
                    return 'object'
        return f"neither a root nor an object: {path}"
    return f"unexpected path type: {path}"

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'  - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return f"not found: {path}"
    if os.path.isfile(path):
        return 'file'
    if not os.path.isdir(path):
        return f"neither file nor directory: {path}"
    try:
        entries = os.listdir(path)
    except OSError as exc:
        return f"cannot list directory {path}: {exc}"

    # Check for OCFL inventory files: "0=*"
    for name in entries:
        full = os.path.join(path, name)
        if os.path.isfile(full) and name.startswith("0="):
            return 'object'

    # Common marker for an OCFL storage root is an "objects" sub‑directory
    if "objects" in entries and os.path.isdir(os.path.join(path, "objects")):
        return 'root'

    # If none of the above matched, provide a helpful explanation
    if entries:
        return f"unknown type (contains entries: {', '.join(entries)})"
    return f"empty directory (no indication of OCFL root or object): {path}"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params

    Ensures the params dictionary contains the correct ``ids`` key for
    operations that target one or more Bugzilla bugs. If ``bug_ids`` is a
    single integer it is converted to a string; if it is an iterable,
    the values are joined with commas. Existing ids will be merged.

    Returns the amended dictionary.
    """
    if not bug_ids:
        return params

    # Normalise bug_ids to a comma separated string
    if isinstance(bug_ids, (str, bytes)):
        ids_string = bug_ids
    else:
        try:
            iter(bug_ids)
        except TypeError:
            ids_string = str(bug_ids)
        else:
            ids_string = ",".join(str(b) for b in bug_ids)

    # Merge with any existing ids in params
    if "ids" in params:
        if isinstance(params["ids"], str):
            params["ids"] = f"{params['ids']},{ids_string}"
        else:
            # Convert to list of strings and merge
            existing = [str(x) for x in params["ids"]]
            params["ids"] = ",{0}".format(ids_string)  # add new ids
            params["ids"] = ",".join(existing + [ids_string])
    else:
        params["ids"] = ids_string

    # Bugzilla uses `ids` for multiple bugs; remove any stray `id`
    params.pop("id", None)

    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    # Ensure we are operating on a dictionary
    if not isinstance(params, dict):
        raise ValueError("params must be a dict")

    # Convert the passed bug_ids into a comma separated string (Bugzilla expects this format)
    if isinstance(bug_ids, (list, tuple)):
        params['ids'] = ','.join(str(bug_id) for bug_id in bug_ids)
    else:
        params['ids'] = str(bug_ids)

    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Expect params to be a dictionary that will be passed to the Bugzilla
    # request.  The Bugzilla API accepts a comma‑separated list of bug ids
    # under the key 'ids'.  Ensure we always store the ids in this format.
    if isinstance(bug_ids, (list, tuple)):
        params['ids'] = ','.join(map(str, bug_ids))
    else:
        params['ids'] = bug_ids

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params"""
        # BUGS:
        #  - If bug_ids is a single scalar, store it under 'id'.
        #  - If bug_ids is a list/tuple/set, join them into a comma‑separated
        #    string and set under 'ids'.
        #  - If 'ids' already exists we merge the new ids into the list,
        #    ensuring no duplicates.
        if not bug_ids:
            return

        # Helper to format list of ids
        def _format_ids(ids):
            return ','.join(str(i) for i in ids)

        # If already has 'ids', merge
        if 'ids' in params:
            existing = params.get('ids', '')
            if existing:
                existing_ids = [i.strip() for i in existing.split(',') if i.strip()]
            else:
                existing_ids = []
            if isinstance(bug_ids, (list, tuple, set)):
                new_ids = [str(i) for i in bug_ids]
            else:
                new_ids = [str(bug_ids)]
            # merge while preserving order and removing duplicates
            merged = list(dict.fromkeys(existing_ids + new_ids))
            params['ids'] = _format_ids(merged)
        else:
            if isinstance(bug_ids, (list, tuple, set)):
                params['ids'] = _format_ids(bug_ids)
            else:
                params['id'] = str(bug_ids)

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def is_mapping(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    def merge_mapping_nodes(m1, m2):
        '''
        Recursively merge two MappingNode instances (m1 and m2) and return a new
        MappingNode with the merged content. The order of keys from m1 is preserved;
        new keys from m2 are appended at the end.
        '''
        items1 = m1.value
        items2 = m2.value
        new_items = []
        key_positions = {}
        for idx, (k, v) in enumerate(items1):
            new_items.append((k, v))
            key_positions[k.value] = idx

        for k2, v2 in items2:
            key_val = k2.value
            if key_val in key_positions:
                idx = key_positions[key_val]
                existing_k, existing_v = new_items[idx]
                if is_mapping(existing_v) and is_mapping(v2):
                    merged_v = merge_mapping_nodes(existing_v, v2)
                    new_items[idx] = (existing_k, merged_v)
                else:
                    new_items[idx] = (existing_k, v2)
            else:
                new_items.append((k2, v2))
        # Construct a new MappingNode preserving the original tag
        return type(m1)(tag=m1.tag, value=new_items)

    result = []
    key_index = {}
    for key_node, value_node in nodes:
        key_val = getattr(key_node, 'value', None)
        if key_val in key_index:
            idx = key_index[key_val]
            _, existing_value = result[idx]
            if is_mapping(existing_value) and is_mapping(value_node):
                merged_value = merge_mapping_nodes(existing_value, value_node)
                result[idx] = (result[idx][0], merged_value)
            else:
                # Overwrite with the latest non-mapping value
                result[idx] = (key_node, value_node)
        else:
            key_index[key_val] = len(result)
            result.append((key_node, value_node))
    return result

def deep_merge_nodes(nodes):
    """
    Deep merge nodes with duplicate ScalarNode keys.

    Parameters
    ----------
    nodes : list[tuple[ScalarNode, Node]]
        A list of (key, value) tuples where the key is a ScalarNode and
        the value is a MappingNode, ScalarNode, or other ruamel node.

    Returns
    -------
    list[tuple[ScalarNode, Node]]
        The merged list of nodes containing one entry per unique key.
    """
    # Keep track of merged values per key and the first key node seen
    merged = {}
    first_key_nodes = {}

    for key_node, value_node in nodes:
        key = key_node.value

        if key in merged:
            existing_value = merged[key]
            # Only merge if both are MappingNodes, otherwise last value wins
            try:
                # Use duck typing to check if value_node behaves like a MappingNode
                from ruamel.yaml.nodes import MappingNode  # pylint: disable=import-outside-toplevel
            except Exception:  # pragma: no cover
                # If the import fails we fall back to attribute check
                def is_mapping(n):
                    return hasattr(n, "tag") and hasattr(n, "value") and n.tag.endswith("map")
            else:
                def is_mapping(n):
                    return isinstance(n, MappingNode)

            if is_mapping(existing_value) and is_mapping(value_node):
                # Merge the underlying value lists recursively
                merged_value_list = list(existing_value.value) + list(value_node.value)
                merged[key] = MappingNode(tag=existing_value.tag,
                                          value=deep_merge_nodes(merged_value_list))
            else:
                merged[key] = value_node
        else:
            merged[key] = value_node
            first_key_nodes[key] = key_node

    # Reconstruct the result list preserving the original first key order
    result = []
    for key, value_node in merged.items():
        result.append((first_key_nodes[key], value_node))
    return result

def parse_arguments(*arguments):
