    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to merge two MappingNode objects
    def _merge_mapping_nodes(m1, m2):
        # Build a dict of key_value -> (key_node, value_node) from first mapping
        out_pairs = []
        key_to_pair = {}
        for k_node, v_node in m1.value:
            key_to_pair[k_node.value] = (k_node, v_node)
            out_pairs.append((k_node, v_node))
        # Process second mapping, merging or appending
        for k_node2, v_node2 in m2.value:
            key_val = k_node2.value
            if key_val in key_to_pair:
                # Merge values
                _, existing_v = key_to_pair[key_val]
                if isinstance(existing_v, ruamel.yaml.nodes.MappingNode) and isinstance(v_node2, ruamel.yaml.nodes.MappingNode):
                    merged = _merge_mapping_nodes(existing_v, v_node2)
                else:
                    merged = v_node2
                # Replace existing pair
                for idx, (k, v) in enumerate(out_pairs):
                    if k.value == key_val:
                        out_pairs[idx] = (k_node2, merged)
                        break
                key_to_pair[key_val] = (k_node2, merged)
            else:
                out_pairs.append((k_node2, v_node2))
                key_to_pair[key_val] = (k_node2, v_node2)
        # Create new MappingNode preserving tag from the first
        return ruamel.yaml.nodes.MappingNode(tag=m1.tag, value=out_pairs)

    # Main merge logic
    merged_dict = {}
    first_occurrence = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in merged_dict:
            existing_val = merged_dict[key]
            if isinstance(existing_val, ruamel.yaml.nodes.MappingNode) and isinstance(val_node, ruamel.yaml.nodes.MappingNode):
                merged_val = _merge_mapping_nodes(existing_val, val_node)
                merged_dict[key] = merged_val
            else:
                merged_dict[key] = val_node
        else:
            merged_dict[key] = val_node
            first_occurrence[key] = key_node
    # Build ordered result list
    result = []
    seen = set()
    for key_node, val_node in nodes:
        key = key_node.value
        if key not in seen:
            result.append((first_occurrence[key], merged_dict[key]))
            seen.add(key)
    return result

