def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting borgmatic's command-line argument parsers.
    '''
    try:
        import click
        from importlib import import_module
    except Exception:
        return ""
    # Attempt to load borgmatic CLI click command group
    try:
        borg_module = import_module('borgmatic.cli.main')
    except Exception:
        try:
            borg_module = import_module('borgmatic.cli')
        except Exception:
            return ""
    cmd = getattr(borg_module, 'main', None)
    if cmd is None:
        cmd = getattr(borg_module, 'cli', None)
    if cmd is None:
        return ""
    # Collect subcommand names recursively
    commands = []
    def collect(group, path):
        for name, sub in getattr(group, 'commands', {}).items():
            full = path + [name]
            commands.append(' '.join(full))
            collect(sub, full)
    collect(cmd, [])
    # Build the bash completion function
    commands_pattern = ' '.join(commands)
    lines = []
    lines.append("_borgmatic_completion() {")
    lines.append("    local cur_word=${{COMP_WORDS[COMP_CWORD]}}")
    lines.append(f"    local commands=({commands_pattern})")
    lines.append("    COMPREPLY=( $(compgen -W \"${{commands[@]}}\" -- $cur_word) )")
    lines.append("}")
    lines.append("complete -F _borgmatic_completion borgmatic")
    return '\n'.join(lines)

def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this
    by introspecting borgmatic's command-line argument parsers.
    """
    import importlib
    try:
        mod = importlib.import_module('borgmatic.cli.main')
    except Exception:
        return '# Unable to import borgmatic CLI module'

    # Try to obtain the root click command; it might be named `cli` or `borgmatic`
    cli_cmd = getattr(mod, 'cli', None)
    if cli_cmd is None:
        # Fallback: look for click.Command objects in the module
        for name, value in vars(mod).items():
            if hasattr(value, 'commands') and hasattr(value, 'get_params'):
                cli_cmd = value
                break
        if cli_cmd is None:
            return '# No click command found in borgmatic CLI module'

    # Recursively collect all options and subcommand names
    def collect_params(cmd, prefix=''):
        items = []
        for param in cmd.get_params(None):
            # In Click, options have `opts` list; arguments have `name`
            if hasattr(param, 'opts'):
                opt = max(param.opts, key=len)
                items.append(f"{prefix}{opt}")
        for sub_name, sub_cmd in getattr(cmd, 'commands', {}).items():
            # Subcommands are appended with a space to indicate hierarchy
            items.extend(collect_params(sub_cmd, f"{prefix}{sub_name} "))
        return items

    param_list = collect_params(cli_cmd)

    # Generate a simple bash completion function that uses compgen
    completion_script = f"""
_borgmatic_completion() {{
    local cur prev words cword
    _get_comp_words_by_ref cur prev words cword

    local comps=("$({{compgen -W \"{' '.join(param_list)}\" -- ${{cur}}}})")
    COMPREPLY=(${{comps[@]}})
    return 0
}}
complete -F _borgmatic_completion borgmatic
""".strip()

    return completion_script

