            "((?:\\.|[^"\\])*)"           # double quoted
            |'((?:\\.|[^'\\])*)'          # single quoted
            |([^'"\s]+)                   # unquoted
        )
    ''', re.VERBOSE)
    args = []
    pos = 0
    for m in pattern.finditer(s):
        # Skip leading whitespace
        if m.start() > pos:
            intervening = s[pos:m.start()]
            if re.search(r'[^\s]', intervening):
                # Unexpected characters between tokens
                pass
        pos = m.end()
        dbl, sgl, nonq = m.group(1, 2, 3)
        if dbl is not None:
            token = dbl.replace(r'\"', '"').replace(r'\n', '\n').replace(r'\\', '\\')
        elif sgl is not None:
            token = sgl.replace(r"\'", "'").replace(r'\n', '\n').replace(r'\\', '\\')
        else:
            token = nonq
        args.append(token)
    # Handle any trailing whitespace
    if pos < len(s):
        trailing = s[pos:]
        if re.search(r'[^\s]', trailing):
            # unexpected trailing characters
            pass
    return args

