def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq = frequency.strip()
    else:
        freq = str(frequency).strip()
    if freq.lower() == 'always':
        return None

    parts = freq.split(None, 1)
    if len(parts) != 2:
        raise ValueError("frequency string must contain a number and a unit")
    number_str, unit = parts
    try:
        num = int(number_str)
    except ValueError:
        raise ValueError(f"cannot parse number part '{number_str}'")

    unit = unit.lower().strip()
    time_map = {
        'second': 'seconds',
        'seconds': 'seconds',
        'minute': 'minutes',
        'minutes': 'minutes',
        'hour': 'hours',
        'hours': 'hours',
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
    }

    if unit not in time_map:
        raise ValueError(f"unknown time unit '{unit}'")
    kwargs = {time_map[unit]: num}
    return datetime.timedelta(**kwargs)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

