def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    if os.name != 'nt':
        return False
    # Git Bash sets MSYSTEM environment variable (e.g., MINGW64)
    if os.getenv('MSYSTEM'):
