def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize the commands argument to a list
    if isinstance(commands, str):
        command = [commands]
    else:
        command = list(commands)

    # Append additional arguments if provided
    if args:
        if isinstance(args, list):
            command.extend(args)
        elif isinstance(args, dict):
            for key, value in args.items():
                command.append(str(key))
                if value is not None:
                    command.append(str(value))
        else:
            command.append(str(args))

    # Verbose output
    if verbose:
        print(f"Running command: {' '.join(command)}")

    # Handle stderr visibility
    stderr_option = subprocess.DEVNULL if hide_stderr else None

    # Execute the command
    result = subprocess.run(
        command,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=stderr_option,
        text=True
    )

    # Raise error if command failed
    if result.returncode != 0:
        raise subprocess.CalledProcessError(
            result.returncode,
            command,
            output=result.stdout,
            stderr=result.stderr
        )

    return result.stdout

