def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os, logging
    try:
        import yaml
    except ImportError:
        yaml = None
    try:
        import toml
    except ImportError:
        toml = None

    def _interpolate(value):
        if isinstance(value, dict):
            return {k: _interpolate(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_interpolate(v) for v in value]
        if isinstance(value, str):
            return os.path.expandvars(value)
        return value

    configs = {}
    errors = []

    for fname in config_filenames:
        cfg = None
        try:
            with open(fname, 'r') as fd:
                raw = fd.read()
            ext = os.path.splitext(fname)[1].lower()
            if ext in ('.toml', '.tml'):
                if toml is None:
                    raise RuntimeError('toml module is not available')
                cfg = toml.loads(raw)
            else:
                if yaml is None:
                    raise RuntimeError('yaml module is not available')
                cfg = yaml.safe_load(raw)
            if resolve_env:
                cfg = _interpolate(cfg)
            if overrides and isinstance(cfg, dict):
                cfg.update(overrides)
        except Exception as exc:
            rec = logging.LogRecord(
                name=os.path.basename(fname),
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=None
            )
            errors.append(rec)
            cfg = None
        configs[fname] = cfg

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        - dict of configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    '''
    config_dict = {}
    error_records = []

    # Helper for merging two dictionaries recursively
    def _deep_merge(base, upd):
        for key, val in upd.items():
            if key in base and isinstance(base[key], dict) and isinstance(val, dict):
                _deep_merge(base[key], val)
            else:
                base[key] = val

    # Helper for environment variable substitution
    def _resolve_env(value):
        import os, re
        if isinstance(value, str):
            pattern = re.compile(r'\${([^}]+)}')
            def repl(match):
                return os.getenv(match.group(1), '')
            return pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        else:
            return value

    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                raw = f.read()
        except Exception as exc:
            record = logging.LogRecord('load_configurations', logging.ERROR,
                                       pathlib.Path(fname).resolve().as_posix(),
                                       0, f"Failed to read file: {exc}", None, None)
            error_records.append(record)
            continue

        # Determine parser by file extension
        try:
            if fname.endswith('.json'):
                import json
                parsed = json.loads(raw)
            elif fname.endswith(('.yaml', '.yml')):
                import yaml
                parsed = yaml.safe_load(raw) or {}
            elif fname.endswith('.toml'):
                import toml
                parsed = toml.loads(raw)
            elif fname.endswith('.ini') or fname.endswith('.cfg'):
                import configparser
                parser = configparser.ConfigParser()
                parser.read_string(raw)
                parsed = {section: dict(parser.items(section)) for section in parser.sections()}
            else:
                raise ValueError(f"Unsupported configuration file format: {fname}")
        except Exception as exc:
            record = logging.LogRecord('load_configurations', logging.ERROR,
                                       pathlib.Path(fname).resolve().as_posix(),
                                       0, f"Failed to parse config: {exc}", None, None)
            error_records.append(record)
            continue

        if overrides is not None and isinstance(overrides, dict):
            # Handle override file or dictionary
            if isinstance(overrides, str) and os.path.isfile(overrides):
                try:
                    with open(overrides, 'r') as fov:
                        o_raw = fov.read()
                    if overrides.endswith('.json'):
                        o_parsed = json.loads(o_raw)
                    elif overrides.endswith(('.yaml', '.yml')):
                        o_parsed = yaml.safe_load(o_raw) or {}
                    elif overrides.endswith('.toml'):
                        o_parsed = toml.loads(o_raw)
                    else:
                        o_parsed = {}
                    _deep_merge(parsed, o_parsed)
                except Exception as exc:
                    record = logging.LogRecord('load_configurations', logging.ERROR,
                                               pathlib.Path(overrides).resolve().as_posix(),
                                               0, f"Failed to load overrides: {exc}", None, None)
                    error_records.append(record)
            elif isinstance(overrides, dict):
                _deep_merge(parsed, overrides)

        if resolve_env:
            parsed = _resolve_env(parsed)

        if not isinstance(parsed, dict):
            record = logging.LogRecord('load_configurations', logging.ERROR,
                                       pathlib.Path(fname).resolve().as_posix(),
                                       0, f"Parsed configuration is not a dictionary.", None, None)
            error_records.append(record)
            continue

        config_dict[fname] = parsed

    return config_dict, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        - dict of configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import sys
    import json
    import yaml
    import logging
    try:
        import toml
    except Exception:
        toml = None
    try:
        import configparser
    except Exception:
        configparser = None

    configs = {}
    error_records = []

    def _make_error_record(file, exc):
        exc_info = sys.exc_info()
        return logging.LogRecord(
            name="config_loader",
            level=logging.ERROR,
            pathname=file,
            lineno=0,
            msg=f"Failed to parse {file}: {exc}",
            args=None,
            exc_info=exc_info,
        )

    def _resolve_env_value(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        elif isinstance(value, dict):
            return {k: _resolve_env_value(v) for k, v in value.items()}
        elif isinstance(value, (list, tuple)):
            return type(value)(_resolve_env_value(v) for v in value)
        else:
            return value

    for filename in config_filenames:
        if not os.path.isfile(filename):
            error_records.append(_make_error_record(filename, "File does not exist"))
            continue
        ext = os.path.splitext(filename)[1].lower()
        parsed = None
        try:
            if ext in {".yaml", ".yml"}:
                with open(filename, "r") as f:
                    parsed = yaml.safe_load(f)
            elif ext == ".json":
                with open(filename, "r") as f:
                    parsed = json.load(f)
            elif ext == ".toml" and toml is not None:
                with open(filename, "r") as f:
                    parsed = toml.loads(f.read())
            elif ext in {".ini", ".cfg"} and configparser is not None:
                parser = configparser.ConfigParser()
                parser.read(filename)
                parsed = {section: dict(parser.items(section)) for section in parser.sections()}
            else:
                raise ValueError(f"Unsupported file extension: {ext}")
        except Exception as e:
            error_records.append(_make_error_record(filename, e))
            parsed = None

        if parsed is not None:
            if resolve_env:
                parsed = _resolve_env_value(parsed)
            if overrides and isinstance(parsed, dict):
                parsed.update(overrides)
        configs[filename] = parsed

    return configs, error_records

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """

        # Gather all handler classes that define a PROTOCOL_INFO attribute
        handlers = {}
        for attr in vars(cls).values():
            if isinstance(attr, type) and hasattr(attr, "PROTOCOL_INFO"):
                version = getattr(attr, "PROTOCOL_INFO")
                # Ensure the version is a tuple of two integers
                if (
                    isinstance(version, tuple)
                    and len(version) == 2
                    and all(isinstance(v, int) for v in version)
                ):
                    handlers[version] = attr

        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    f"protocol_version must be a tuple of (major, minor), got {type(protocol_version).__name__}"
                )
            return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

        return handlers

