    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")

    # Fetch the registry of handlers defined on the class
    handlers = getattr(cls, "PROTOCOL_HANDLERS", {})

    # Determine which protocol versions are considered supported.
    # A class may expose `supported_protocols` as a property, method, or attribute.
    supported = getattr(cls, "supported_protocols", None)
    if supported is None:
        # If nothing is specified, assume all registered handlers are supported.
        supported = list(handlers.keys())
    elif callable(supported):
        supported = supported()
    else:
        supported = list(supported)

    # Filter handlers based on supported versions
    if protocol_version is None:
        # Return all supported handlers
        return {v: h for v, h in handlers.items() if v in supported}
    else:
        # Return only the requested handler if supported
        if protocol_version in supported and protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        else:
            return {}

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Direct sequence types: return as is
    if isinstance(seq, (bytes, bytearray)):
        return seq, 'bytes'
    if isinstance(seq, str):
        return seq, 'string'
    # Iterable but not a direct sequence type: join elements
    if hasattr(seq, "__iter__") and not isinstance(seq, (bytes, bytearray, str)):
        try:
            # Try to join iterable elements into a string or bytes
            # Preserve type if elements are bytes
            if all(isinstance(x, bytes) for x in seq):
                return b"".join(seq), 'bytes'
            return "".join(seq), 'string'
        except Exception:
            pass
    # File-like objects: read contents
    if hasattr(seq, "read"):
        if bufsize:
            chunks = []
            while True:
                data = seq.read(bufsize)
                if not data:
                    break
                chunks.append(data)
            # Join based on data type
            if all(isinstance(x, bytes) for x in chunks):
                seqstr = b"".join(chunks)
            else:
                seqstr = "".join(chunks)
        else:
            seqstr = seq.read()
        return seqstr, type(seq).__name__
    # Fallback: return the object itself
    return seq, type(seq).__name__

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Import Sequence only if not already imported
    from collections.abc import Sequence
    # If seq is already a sequence type (but not a string/bytes), return it
    if isinstance(seq, Sequence) and not isinstance(seq, (str, bytes, bytearray)):
        return (seq, type(seq).__name__)
    # If seq is a file-like object, read from it
    if hasattr(seq, "read"):
        data = seq.read(bufsize) if bufsize is not None else seq.read()
        return (data, type(seq).__name__)
    # Otherwise, try to convert to a string representation
    try:
        s = str(seq)
        return (s, type(seq).__name__)
    except Exception:
        # Fallback: return the original object with its type
        return (seq, type(seq).__name__)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Treat string and bytes as scalar values
    if isinstance(seq, (str, bytes)):
        return (seq, "scalar")
    # Determine if seq is an iterable (but not a string/bytes)
    if hasattr(seq, "__iter__"):
        # If it behaves like a file, keep the file object itself
        if hasattr(seq, "read"):
            return (seq, "file")
        # For generic iterables, materialise into a list
        return (list(seq), "iterable")
    # Fallback: treat as a scalar value
    return (seq, "scalar")

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    # Helper to determine whether a value is considered a sequence.
    # Strings and bytes are excluded.
    try:
        from six import string_types, binary_type
    except Exception:
        string_types = (str,)
        binary_type = (bytes,)
    def _is_sequence(value):
        return hasattr(value, "__iter__") and not isinstance(value, (string_types, binary_type))

    # If seq is already a sequence we keep it; otherwise we create a list.
    if _is_sequence(seq):
        sequence = seq
    else:
        try:
            sequence = list(seq)
        except TypeError:
            # If seq cannot be turned into a list, fall back to a single element list.
            sequence = [seq]

    # Apply optional buffer size.
    if bufsize is not None:
        try:
            # If the sequence supports slicing/len, use it.
            if hasattr(sequence, "__len__") or hasattr(sequence, "__getitem__"):
                sequence = sequence[:bufsize]
            else:
                # Fall back to iterating up to bufsize.
                import itertools
                sequence = list(itertools.islice(sequence, bufsize))
        except Exception:
            # If anything goes wrong we simply ignore bufsize.
            pass

    return (sequence, type(seq))

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    Checks that candidate is a subclass (if candidate is a class)
    of iface, or implements all methods/attributes defined in iface.
    Raises TypeError if required members are missing.
    """
    # Determine the class of the candidate
    cls = candidate if isinstance(candidate, type) else getattr(candidate, "__class__", None)
    if cls is None:
        raise TypeError("candidate %r does not appear to be a class or instance with a __class__" % (candidate,))

    # If candidate is already a subclass of the interface, we're done
    try:
        if issubclass(cls, iface):
            return
    except TypeError:
        # `iface` might not be a class, fall back to attribute checking
        pass

    # Collect names from the interface, ignoring private ones
    required_members = [name for name in dir(iface) if not name.startswith("_")]

    missing = []
    for name in required_members:
        iface_member = getattr(iface, name, None)
        # Skip magic methods or objects that aren't callable/attributes, unless the interface explicitly expects them
        if iface_member is None:
            continue
        # Check existence and type in candidate
        cand_member = getattr(cls, name, None)
        if cand_member is None:
            missing.append(name)
        elif callable(iface_member):
            if not callable(cand_member):
                missing.append(name)
        else:
            # For non-callable members, just ensure attribute exists
            pass

    if missing:
        raise TypeError(
            f"Class {cls.__name__} does not implement required members of interface "
            f"{iface.__name__}: {', '.join(missing)}"
        )

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Candidate might be a class or an instance; normalize to a type
    cand_type = candidate if isinstance(candidate, type) else type(candidate)

    # If iface is a tuple of classes, check subclass against any of them
    if isinstance(iface, tuple):
        if any(issubclass(cand_type, t) for t in iface):
            return True
        # Build a list of required names from all interface classes
        required_names = []
        for iface_cls in iface:
            required_names.extend([name for name in dir(iface_cls)
                                   if callable(getattr(iface_cls, name, None))
                                   and not name.startswith('_')])
        required_names = set(required_names)
    else:
        # Single interface class
        if issubclass(cand_type, iface):
            return True
        required_names = [name for name in dir(iface)
                          if callable(getattr(iface, name, None))
                          and not name.startswith('_')]

    # Check that all required attributes are present in the candidate type
    for name in required_names:
        if not hasattr(cand_type, name):
            if tentative:
                continue
            raise TypeError(f"Candidate {cand_type.__name__} must provide method "
                            f"'{name}' required by interface {iface.__name__ if isinstance(iface, type) else ''}")

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type) or not isinstance(candidate, type):
        if tentative:
            return False
        raise TypeError("iface and candidate must be classes")
    missing = []
    for name in dir(iface):
        if name.startswith('_'):
            continue
        if not hasattr(candidate, name):
            missing.append(name)
        else:
            attr_iface = getattr(iface, name)
            attr_candidate = getattr(candidate, name)
            if callable(attr_iface) and not callable(attr_candidate):
                missing.append(name)
    if missing:
        msg = (f"Candidate class {candidate.__name__} is missing "
               f"implementations for: {', '.join(missing)}")
        if tentative:
            return False
        raise TypeError(msg)
    return True

def verifyClass(iface, candidate, tentative=False):
        """
        Verify that the *candidate* might correctly provide *iface*.
        """
        try:
            # If iface is a class/type, verify subclass relationship.
            if isinstance(iface, type):
                if not issubclass(candidate, iface):
                    if tentative:
                        return False
                    raise TypeError(
                        f"Candidate {candidate!r} does not extend interface {iface!r}"
                    )
            else:
                # When iface is iterable of required attribute names.
                required = set(iface)
                missing = [name for name in required if not hasattr(candidate, name)]
                if missing:
                    if tentative:
                        return False
                    raise TypeError(
                        f"Candidate {candidate!r} misses required attributes {missing}"
                    )
        except Exception as exc:
            if tentative:
                return False
            raise exc
        return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass was supplied (Python 2 style), use it after validation
    if explicit_mc is not None:
        for base in bases:
            base_meta = type(base)
            if not issubclass(explicit_mc, base_meta):
                raise TypeError(
                    f"Explicit metaclass {explicit_mc!r} is not compatible with base "
                    f"{base!r} metaclass {base_meta!r}"
                )
        return explicit_mc

    # No explicit metaclass: determine the most derived metaclass from the bases
    if not bases:
        return type  # No bases, default metaclass

    # Build a set of the metaclasses of all bases
    metaclasses = {type(base) for base in bases}

    # Find a metaclass that is a subclass of all others
    common_meta = None
    for meta in metaclasses:
        if all(issubclass(meta, other) or meta is other for other in metaclasses):
            common_meta = meta
            break

    # If there's no common metaclass that can serve as a more derived type,
    # fall back to the metaclass of the first base
    if common_meta is None:
        common_meta = type(bases[0])

    return common_meta

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit_metaclass must be a type")
        metaclass = explicit_mc
    elif bases:
        metaclass = type(bases[0])
    else:
        metaclass = type

    for base in bases:
        base_meta = type(base)
        if metaclass is base_meta:
            continue
        if issubclass(metaclass, base_meta):
            continue
        if issubclass(base_meta, metaclass):
            metaclass = base_meta
            continue
        raise TypeError("metaclass conflict: %s vs %s" % (metaclass.__name__, base_meta.__name__))
    return metaclass

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    if not bases:
        return type
    metas = [type(b) for b in bases]
    # Compute the intersection of the MROs of the candidate metaclasses
    mro_lists = [m.mro() for m in metas]
    common = set(mro_lists[0])
    for mro in mro_lists[1:]:
        common.intersection_update(mro)
    if not common:
        raise TypeError("metaclass conflict: no common ancestor between metaclasses")
    # Choose the most derived metaclass: the one that appears earliest in the
    # MRO of the first metaclass in the list
    chosen = None
    for m in mro_lists[0]:
        if m in common:
            chosen = m
            break
    return chosen or type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        # In Python explicit metaclass must be a type
        if not isinstance(explicit_mc, type):
            raise TypeError("__metaclass__ must be a type")
        return explicit_mc

    if not bases:
        # No bases: default to 'type'
        return type

    # Helper to get the metaclass of a base
    def metaclass_of(base):
        try:
            return type(base)
        except Exception:
            # Fallback if type lookup fails
            return type

    # Start with the metaclass of the first base
    candidate = metaclass_of(bases[0])
    for base in bases[1:]:
        base_meta = metaclass_of(base)

        if issubclass(base_meta, candidate):
            # Prefer the more derived metaclass
            candidate = base_meta
        elif not issubclass(candidate, base_meta):
            # No common metaclass exists
            raise TypeError(
                f"metaclass conflict: {candidate.__name__} is not compatible with {base_meta.__name__}"
            )
        # else: candidate is already a subclass of base_meta, keep it

    return candidate

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is __marker:
            raise KeyError(key)
        return default
    return super().pop(key)

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)
    return super().pop(key)

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    # First, check if the key exists in the mapping
    if key not in self:
        if default is __marker:
            raise KeyError(key)
        return default

    # Attempt to find and remove the key from the various protobuf maps
    for map_obj in (self._pb.IntMap, self._pb.FloatMap,
                    self._pb.StringMap, self._pb.BoolMap):
        if key in map_obj:
            return map_obj.pop(key)

    # If the key was present in the container but not in any known map,
    # fall back to the default if provided, else raise an error.
    if default is __marker:
        raise KeyError(key)
    return default

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        val = self[key]
    except KeyError:
        if default is not __marker:
            return default
        raise
    del self[key]
    return val

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    try:
        # determine the least frequently used frequency
        min_freq = min(self._freq.values())
        # find any key that has this frequency
        for key in self._freq:
            if self._freq[key] == min_freq:
                value = self._data.pop(key)
                self._freq.pop(key)
                return (key, value)
    except (KeyError, ValueError):
        # handle empty or missing internal structures
        raise KeyError('dict is empty')

