def default_tzinfo(dt, tzinfo):
    """
    Sets the ``tzinfo`` parameter on naive datetimes only

    This is useful for example when you are provided a datetime that may have
    either an implicit or explicit time zone, such as when parsing a time zone
    string.
    """
    if dt is None:
        return None
    # If tzinfo attribute is missing, assume it's a datetime-like object
    has_tzinfo_attr = hasattr(dt, "tzinfo")
    try:
        current_tz = dt.tzinfo if has_tzinfo_attr else None
    except Exception:
        current_tz = None
    # Replace tzinfo only if the datetime is naive (tzinfo is None)
    if current_tz is None:
        return dt.replace(tzinfo=tzinfo)
    return dt

