def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Attempt to retrieve the request path using common attributes
    path = getattr(request, "path", "")
    if not path:
        path = getattr(request, "path_info", "")
    # Matrix endpoints are prefixed with '/_matrix'
    return path.startswith("/_matrix")

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    if not request:
        return False
    # Check the request path for Matrix-specific prefixes
    try:
        path = request.path
    except Exception:
        path = getattr(request, 'get_full_path', lambda: '')()
    if isinstance(path, str) and path.startswith('/_matrix/'):
        return True
    # Check common Matrix headers that may be present
    matrix_header = request.META.get('HTTP_X_MATRIX_SOURCE')
    if matrix_header:
        return True
    # Fallback to content type
    content_type = request.META.get('CONTENT_TYPE', '')
    if content_type == 'application/json':
        return True
    return False

