    return False

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    # Check the request path for the Matrix API prefix
    path_attr = None
    if hasattr(request, "path"):
        path_attr = "path"
    elif hasattr(request, "path_info"):
        path_attr = "path_info"
    if path_attr:
        path = getattr(request, path_attr, "")
        if isinstance(path, str) and path.startswith("/_matrix"):
            return True

    # Fallback: check the Content-Type header for a typical Matrix JSON payload
    content_type = None
    if hasattr(request, "content_type"):
        content_type = getattr(request, "content_type", None)
    if content_type is None and hasattr(request, "META"):
        content_type = request.META.get("CONTENT_TYPE")
    if content_type and content_type.lower().startswith("application/json"):
        return True

    return False

