    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # Accept timestamp numbers
    if isinstance(dt, (int, float)):
        dt = datetime.datetime.utcfromtimestamp(dt)
    # Accept date objects
    if isinstance(dt, datetime.date) and not isinstance(dt, datetime.datetime):
        dt = datetime.datetime.combine(dt, datetime.time.min)
    # Convert timezone-aware datetimes to UTC
    if hasattr(dt, "tzinfo") and dt.tzinfo is not None:
        dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
    # Return ISO 8601 string ending with 'Z'
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Regular expression to find URLs in the text
    url_re = re.compile(r'\b(?:https?://|www\.)[^\s<>"\'`]+', re.IGNORECASE)

    def repl(match):
        url = match.group(0)
        href = url
        # Make sure www. links are prefixed with http://
        if url.startswith('www.'):
            href = 'http://' + url
        # Return the link with desired attributes
        return (
            f'<a href="{href}" target="_blank" rel="noopener">{url}</a>'
        )

    # Substitute all URLs with linked versions
    return url_re.sub(repl, text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re, os
    pattern = re.compile(r'\b(https?://[^\s]+)\b|(\b[\w./\-]+\b)')
    def replace(m):
        url = m.group(1)
        path = m.group(2)
        if url:
            return f'<a target="_blank" rel="noopener noreferrer" href="{url}">{url}</a>'
        if path:
            if os.path.exists(path):
                return f'<a target="_blank" rel="noopener noreferrer" href="/browse/{path}">{path}</a>'
        return m.group(0)
    return pattern.sub(replace, text)

