def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message."""
    import lxml.etree as ET
    import xmlsec
    try:
        root = ET.fromstring(doc)
    except ET.XMLSyntaxError:
        return False
    if signature is None:
        ns = {"ds": "http://www.w3.org/2000/09/xmldsig#"}
        sigs = root.xpath('//ds:Signature', namespaces=ns)
        if not sigs:
            return False
        signature = sigs[0]
    ctx = xmlsec.SignatureContext()
    key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
    ctx.key = key
    try:
        ctx.verify(signature)
        return True
    except xmlsec.VerificationError:
        return False

def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed author did actually generate this message."""
    # Parse the XML document
    try:
        tree = lxml.etree.fromstring(doc.encode() if isinstance(doc, str) else doc)
    except Exception:
        return False

    # Find the Signature element
    sig_node = tree.find('.//{http://www.w3.org/2000/09/xmldsig#}Signature')
    if sig_node is None:
        return False

    # Create a verification context using the provided public key
    try:
        ctx = xmlsec.SignatureContext()
        manager = xmlsec.KeysManager()
        key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM)
        manager.add_key(key)
        ctx.key_manager = manager

        # Perform the verification
        return ctx.verify(sig_node)
    except Exception:
        return False

