def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if not handle:
            return None
        # Ensure the resource is prefixed with acct:
        if not handle.startswith("acct:"):
            resource = f"acct:{handle}"
        else:
            resource = handle
        # Extract host from the handle
        _, host = resource.split("@", 1)
        # Construct the webfinger URL
        url = f"https://{host}/.well-known/webfinger?resource={urllib.parse.quote(resource)}"
        # Perform the GET request
        with urllib.request.urlopen(url, timeout=10) as resp:
            return resp.read().decode("utf-8")
    except Exception:
        return None

