def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    logger.debug("send_document: url=%s, data=%s, timeout=%s, method=%s",
                 url, data, timeout, method)
    headers = CaseInsensitiveDict({
        'User-Agent': USER_AGENT,
    })
    if "headers" in kwargs:
        headers.update(kwargs.get("headers"))
    kwargs.update({
        "data": data,
        "timeout": timeout,
        "headers": headers
    })
    try:
        m = method.lower()
        if m == "post":
            response = requests.post(url, *args, **kwargs)
        elif m == "get":
            response = requests.get(url, *args, **kwargs)
        else:
            response = requests.request(method, url, *args, **kwargs)
        logger.debug("send_document: response status code %s", response.status_code)
        return response.status_code, None
    except RequestException as ex:
        logger.debug("send_document: exception %s", ex)
        return None, ex

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    logger.debug("send_document: url=%s, data=%s, timeout=%s, method=%s", url, data, timeout, method)
    headers = CaseInsensitiveDict({
        'User-Agent': USER_AGENT,
    })
    # Update headers from kwargs if provided
    if "headers" in kwargs:
        headers.update(kwargs.get("headers"))

    # Prepare kwargs for the request
    kwargs.update({
        "data": data,
        "timeout": timeout,
        "headers": headers
    })

    try:
        # Choose the request function based on the method
        meth = method.lower()
        if meth == "post":
            response = requests.post(url, *args, **kwargs)
        elif meth == "get":
            response = requests.get(url, *args, **kwargs)
        else:
            raise ValueError(f"Unsupported method '{method}'")
        logger.debug("send_document: response status code %s", response.status_code)
        return response.status_code, None
    except RequestException as ex:
        logger.debug("send_document: exception %s", ex)
        return None, ex

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    files = []
    for dir_path in settings_dirs:
        try:
            for fname in os.listdir(dir_path):
                if spec_option:
                    if fnmatch.fnmatch(fname, spec_option):
                        files.append(os.path.join(dir_path, fname))
                else:
                    files.append(os.path.join(dir_path, fname))
        except OSError:
            continue
    return sorted(files)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    import os
    # Ensure spec_option is a set of desired extensions (without the dot)
    if spec_option:
        spec_set = {ext.lstrip('.') for ext in spec_option}
    else:
        spec_set = None
    filenames = []
    for directory in settings_dirs:
        if not os.path.isdir(directory):
            continue
        try:
            for fname in os.listdir(directory):
                ext = os.path.splitext(fname)[1].lstrip('.')
                # If spec_option is provided, skip files whose extension is not in the set
                if spec_set is not None and ext not in spec_set:
                    continue
                if fname.lower().endswith('.ini'):
                    filenames.append(os.path.join(directory, fname))
        except OSError:
            # Skip directories we cannot read
            continue
    filenames.sort()
    # Return an IniType complex type instantiated with the collected filenames
    return IniType(filenames=filenames)

def list_of_file_names(settings_dirs, spec_option=None):
    """Create a new IniType complex type
    """
    # Normalize settings_dirs to a list
    if not isinstance(settings_dirs, (list, tuple)):
        settings_dirs = [settings_dirs]
    files = []
    try:
        for directory in settings_dirs:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                if spec_option and not fname.endswith(spec_option):
                    continue
                files.append(os.path.join(directory, fname))
        return sorted(files)
    except OSError:
        return []

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    file_list = []
    for directory in settings_dirs:
        try:
            if isinstance(spec_option, str):
                pattern = os.path.join(directory, spec_option)
                file_list.extend(glob(pattern))
            else:
                for ext in spec_option:
                    ext = f".{ext}" if not ext.startswith(".") else ext
                    pattern = os.path.join(directory, f"*{ext}")
                    file_list.extend(glob(pattern))
        except Exception:
            # ignore directories that cannot be accessed
            pass
    return sorted(set(file_list))

