def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("No spec content provided")
        try:
            data = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f"Error parsing YAML content: {e}") from e
        if not isinstance(data, dict):
            raise IRValidatorException("YAML content does not represent a mapping")
        missing = [fld for fld in cls.REQUIRED_FIELDS if fld not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields in spec: {', '.join(missing)}")
        return data

def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Ensure spec content has been supplied
        if spec_content is None:
            raise IRValidatorException("No spec content supplied for validation")

        # If content is a string or bytes, parse it as YAML
        if isinstance(spec_content, (str, bytes)):
            try:
                spec_data = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Error parsing spec content: {exc}")
        elif isinstance(spec_content, dict):
            spec_data = spec_content
        else:
            raise IRValidatorException(f"Unsupported spec content type: {type(spec_content)}")

        # Validate that we have a mapping (dictionary)
        if not isinstance(spec_data, dict):
            raise IRValidatorException(f"Parsed spec content is not a mapping: {type(spec_data)}")

        # Determine required fields - either provided by class or deduced
        required_fields = getattr(cls, 'REQUIRED_FIELDS', None)
        if required_fields is None:
            # Default expectation of a spec: it must have a 'name' and a 'schema' section
            required_fields = ['name', 'schema']

        # Check each required field
        missing_fields = [f for f in required_fields if f not in spec_data]
        if missing_fields:
            raise IRValidatorException(f"Missing required fields in spec: {', '.join(missing_fields)}")

        return spec_data

def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException('No spec content provided.')

        # Parse the YAML content.  `safe_load` is used to avoid arbitrary
        # code execution while still handling the most common data types.
        try:
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f'Unable to parse YAML: {exc}')

        if not isinstance(data, dict):
            raise IRValidatorException('Spec must be a YAML mapping (dictionary).')

        # Define the set of fields that are mandatory for a valid spec.
        # These may change over time; keep them here so the validation logic
        # is in one place.
        required_fields = {
            'name': str,        # Name of the spec
            'type': str,        # Type of spec
            'version': (int, str)  # Semantic version; either int or string
        }

        missing = []
        wrong_type = []

        for key, expected_type in required_fields.items():
            if key not in data:
                missing.append(key)
            else:
                # Handle multiple expected types
                if isinstance(expected_type, tuple):
                    valid = any(isinstance(data[key], t) for t in expected_type)
                else:
                    valid = isinstance(data[key], expected_type)
                if not valid:
                    wrong_type.append((key, expected_type, type(data[key])))

        if missing:
            raise IRValidatorException(
                f'Missing mandatory field(s) in spec: {", ".join(missing)}'
            )
        if wrong_type:
            messages = [
                f'{k} expected {t} but got {got}'
                for k, t, got in wrong_type
            ]
            raise IRValidatorException(f'Invalid field types: {"; ".join(messages)}')

        return data

