        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise ValueError("yaml_file argument must be supplied")
        # Support string paths as well as pathlib.Path objects
        if not isinstance(yaml_file, (Path, str)):
            raise TypeError("yaml_file must be a Path or str")
        path = yaml_file if isinstance(yaml_file, Path) else Path(yaml_file)
        if not path.is_file():
            raise FileNotFoundError(f"File not found: {path}")
        try:
            with path.open('r', encoding='utf-8') as f:
                data = yaml.safe_load(f)
        except Exception as exc:
            # Any YAML parsing error results in an IRValidatorException
            raise IRValidatorException(f"Error parsing YAML file {path}: {exc}") from exc
        # Ensure data is a dictionary
        if not isinstance(data, dict):
            raise IRValidatorException(f"YAML file {path} does not contain a mapping at the top level")
        # Validate presence of mandatory fields
        for field in getattr(cls, "REQUIRED_FIELDS", []):
            if field not in data or data[field] in (None, '', []):
                raise IRValidatorException(f"Missing mandatory field '{field}' in file {path}")
        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    includes = parser_dict.pop('include', {})
    if not includes:
        return parser_dict

    def _merge(target, source):
        """Merge a source dictionary into a target dictionary recursively."""
        for k, v in source.items():
            if k in target:
                if isinstance(target[k], dict) and isinstance(v, dict):
                    _merge(target[k], v)
                elif isinstance(target[k], list) and isinstance(v, list):
                    target[k].extend(v)
                else:
                    target[k] = v
            else:
                target[k] = v

    for group, src in includes.items():
        # Resolve source which can be a path or a dictionary
        if isinstance(src, str):
            # Load parser spec from a file (implementation specific)
            sub_parser_dict = self._load_parser_spec(src)
        else:
            sub_parser_dict = src

        # Merge the included group into current parser dictionary
        if group in sub_parser_dict:
            if group in parser_dict:
                _merge(parser_dict[group], sub_parser_dict[group])
            else:
                parser_dict[group] = sub_parser_dict[group]

    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # If there's no include directive just return the dict unchanged
    include = parser_dict.pop('include', None)
    if not include:
        return parser_dict
    # Merge each entry in the include dictionary into the main parser_dict.
    # If the target key is already a dict we update it; otherwise we simply
    # assign the new value.
    for key, val in include.items():
        if isinstance(val, dict):
            parser_dict.setdefault(key, {}).update(val)
        else:
            parser_dict[key] = val
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # Create a new dictionary that has the include directives resolved.
    resolved = {}
    for key, value in parser_dict.items():
        # If the current value is a dict that contains an 'include' key,
        # merge the referenced sections into the current dict.
        if isinstance(value, dict) and 'include' in value:
            # The include key may hold a single name or a list of names.
            include_names = value.pop('include')
            if isinstance(include_names, str):
                include_names = [include_names]
            # Merge each referenced section into a new dict.
            merged = {}
            for inc_name in include_names:
                inc_section = parser_dict.get(inc_name, {})
                if not isinstance(inc_section, dict):
                    # If the referenced item is not a dict, skip it.
                    continue
                merged.update(inc_section)
            # Finally merge the original dict contents (excluding 'include').
            merged.update(value)
            resolved[key] = merged
        else:
            # No include directive, copy the entry as-is.
            resolved[key] = value
    return resolved

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    resolved = {}
    spec = getattr(self, 'spec', None)
    if spec is not None:
        # Include spec values: try dict-like first
        try:
            for k, v in spec.items():
                resolved[k] = v
        except AttributeError:
            # fallback to attribute iteration
            for attr in dir(spec):
                if attr.startswith('_'):
                    continue
                try:
                    resolved[attr] = getattr(spec, attr)
                except Exception:
                    pass
    # Merge with defaults from args
    for arg in getattr(self, 'args', []):
        name = getattr(arg, 'name', None)
        if not name:
            continue
        if name in resolved:
            continue
        # take default from arg if available
        default = getattr(arg, 'default', None)
        if default is not None and default is not NoDefault:
            resolved[name] = default
        # handle nested scheme if dict option
        if hasattr(arg, 'scheme') and arg.scheme:
            nested = arg.scheme.build_defaults()
            if nested:
