    defaults = {}
    for arg in getattr(self, "args", []):
        if not isinstance(arg, _BaseOpt):
            continue

        # Resolve value: first from spec, otherwise use argument's default.
        if hasattr(self, "spec") and hasattr(self.spec, arg.name):
            value = getattr(self.spec, arg.name)
        else:
            value = arg.default if not isinstance(arg.default, NoDefault) else None

        # If the argument is a dict option, merge spec values with scheme defaults.
        if isinstance(arg, DictOption) and isinstance(value, dict):
            if arg.scheme:
                scheme_defaults = arg.scheme.get_spec_defaults()
                scheme_defaults.update(value)
                value = scheme_defaults

        defaults[arg.name] = value
    return defaults

def get_spec_defaults(self):
