        name = arg.name
        # Attempt to get value from spec first
        spec_val = getattr(self.spec, name, None)
        if spec_val is not None:
            defaults[name] = spec_val
        else:
            # Fall back to the option's own default, if it exists
            if not isinstance(arg.default, NoDefault):
                defaults[name] = arg.default
        # If the argument is a dictionary option, recursively gather nested defaults
        if isinstance(arg, DictOption) and getattr(arg, 'scheme', None):
            nested = arg.scheme.build_defaults()
            if nested:
                defaults[name] = nested
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    resolved = {}
    for arg in self.args:
        # Ensure we are dealing with an option type
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError(
                'Unable to resolve default for non-Option type'
            )

        # 1. Try to get a value from the spec (which might be a dict or a mapping object)
        spec_val = None
        if hasattr(self.spec, 'get'):
            try:
                spec_val = self.spec.get(arg.name)
            except Exception:
                spec_val = None
        elif isinstance(self.spec, dict):
            spec_val = self.spec.get(arg.name)

        # 2. If the spec provided a value, use it
        if spec_val is not None:
            resolved[arg.name] = spec_val
            continue

        # 3. If not, fall back to the option's default (if it has one)
        if not isinstance(arg.default, NoDefault):
            resolved[arg.name] = arg.default

        # 4. If this is a dictionary option that interacts with a nested scheme,
        #    recursively gather defaults from that nested scheme
        if isinstance(arg, DictOption) and arg.scheme:
            sub_defaults = arg.scheme.get_spec_defaults()
            if sub_defaults:
                resolved[arg.name] = sub_defaults

    return resolved

