        if isinstance(opt, dict):
            if opt.get("name") == argument_name or opt.get("short") == argument_name:
                return opt
    return None

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")
    # Determine which fields are required; fall back through common attribute names
    required = getattr(self, "required_args", None) or \
               getattr(self, "required", None) or \
               getattr(self, "requires", None)
    if not required:
        return
    missing = [name for name in required if name not in args or args[name] is None]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    # Determine the names of required arguments. Prefer a dedicated attribute
    # but fall back to common naming conventions if not set.
    required = None
    for attr in ('required', 'required_args', 'requires'):
        if hasattr(self, attr):
            required = getattr(self, attr)
            break

    # If the handler does not declare any required arguments, nothing to check.
    if not required:
        return

    # Ensure the argument specification is iterable (list/tuple/iterable).
    for name in required:
        # For dictionary-style args, check key presence and non-None value.
        if isinstance(args, dict):
            if name not in args or args[name] is None:
                raise InvalidArgumentError(f'Required argument "{name}" is missing.')
        # For sequence-style args (e.g., positional arguments), match by index.
        elif isinstance(args, (list, tuple)):
            try:
                index = required.index(name)
                if index >= len(args) or args[index] is None:
                    raise InvalidArgumentError(f'Required positional argument at index {index} is missing.')
            except ValueError:
                # If element name is not found, treat as missing.
                raise InvalidArgumentError(f'Required positional argument "{name}" is missing.')
        else:
            # Unsupported args type
            raise TypeError("Arguments must be a dict or sequence of values.")

def validate_requires_args(self, args):
