    if isinstance(args, dict):
        missing = [name for name in required if name not in args or args[name] is None]
    else:
        # Assume positional arguments: need at least as many items as required
        missing = [] if len(args) >= len(required) else ['missing positional arguments']

    if missing:
        raise ValueError('Missing required arguments: %s' % ', '.join(missing))

