            cond = getattr(opt, 'required_when', None)

        if not name or cond is None:
            continue

        # evaluate condition
        cond_met = False
        if callable(cond):
            try:
                # try passing both command_name and args
                cond_met = cond(command_name, args)
            except TypeError:
                try:
                    cond_met = cond(command_name)
                except TypeError:
                    cond_met = cond(args)
        else:
            # cond may be bool, iterable or mapping
            if isinstance(cond, bool):
                cond_met = cond
            elif isinstance(cond, dict):
                cond_met = all(args.get(k) == v for k, v in cond.items())
            elif isinstance(cond, (list, tuple, set)):
                # treat each item as a flag that must be present
                cond_met = all(item in args for item in cond)
