def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    The function inspects ``options_spec`` – a list of option definition
    dictionaries – and returns a list of option names (the ``arg`` field
    if present, otherwise the ``name`` field) that should be considered
    required because their ``required_when`` condition evaluates to
    ``True`` against the supplied ``args`` and the current ``command_name``.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments (dict-like).
