        cond = opt.get('required_when')
        if cond is None:
            continue

        # Determine whether the condition is satisfied
        match = False
        if callable(cond):
            try:
                match = bool(cond(args))
            except Exception:
                # If the callable throws, treat the condition as not matched
                match = False
        elif isinstance(cond, bool):
            match = cond
        elif isinstance(cond, str):
            # String condition is interpreted as a command name
            match = (cond == command_name)
        elif isinstance(cond, (list, tuple, set)):
            # Either a list of command names or a list of argument names
            if command_name in cond:
                match = True
            else:
                # Treat as list of required arguments – if any is present
                if any(arg in args for arg in cond):
                    match = True
        # Other types are ignored

        if match:
