        name = opt.get('name') or opt.get('arg')
        if name is None:
            continue

        try:
            # Callable condition
            if callable(required_when):
                if required_when(command_name, args):
                    matched.append(name)
                continue

            # Dict mapping: all key/value pairs must match
            if isinstance(required_when, dict):
                if all(args.get(k) == v for k, v in required_when.items()):
                    matched.append(name)
                continue

            # List or tuple of conditions
            if isinstance(required_when, (list, tuple)):
                # If elements are tuples of (key, value)
                if all(isinstance(cond, (list, tuple)) and len(cond) == 2
                       for cond in required_when):
                    if all(args.get(k) == v for k, v in required_when):
                        matched.append(name)
                else:
                    # Treat elements as attribute names that must exist
                    if any(k in args for k in required_when):
                        matched.append(name)
                continue

            # String condition: just a key that must be present
            if isinstance(required_when, str):
                if required_when in args:
                    matched.append(name)
                continue

            # Boolean condition: if True requires the argument
            if isinstance(required_when, bool) and required_when:
                matched.append(name)

        except Exception:
            # If any error evaluating condition, ignore this option
            continue

    return matched

