    for arg_name, arg_value in args.items():
        # Get the spec for this argument.  If no spec, skip length check.
        spec = arg_specs.get(arg_name, {})
        # Length constraints might be stored under different keys; try common ones.
        maxlen = spec.get('maxlength') or spec.get('maxlen')
        if maxlen is None:
            continue  # No length constraint for this argument

        # Ensure the value is something that has a length.
        try:
            val_len = len(arg_value)
        except Exception:
            raise TypeError(f"Cannot determine length of argument '{arg_name}' (value: {arg_value!r})")

        # Raise an error if the length exceeds the allowed maximum.
        if val_len > maxlen:
            raise ValueError(
                f"Argument '{arg_name}' length {val_len} exceeds maximum allowed {maxlen}"
            )

