    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    def _flatten_dict(d, prefix=''):
        flat = {}
        for k, v in d.items():
            key = f'{prefix}{k}' if prefix else k
            if isinstance(v, dict):
                flat.update(_flatten_dict(v, prefix=f'{key}.'))
            else:
                flat[key] = v
        return flat

    # Define keys that belong to control arguments.  These can be
    # extended in subclasses by overriding or assigning to
    # `self.CONTROL_ARGS`.
    control_keys = set(getattr(self, 'CONTROL_ARGS', []))
    control_args = {}
    nested_args = {}

    for key, value in args.items():
        # Remove leading '--' if present (common when parsing CLI args)
        stripped_key = key.lstrip('-')
        if stripped_key in control_keys:
            control_args[stripped_key] = value
        else:
            if isinstance(value, dict):
                nested_args.update(_flatten_dict(value, prefix=f'{stripped_key}.'))
            else:
                nested_args[stripped_key] = value

    return control_args, nested_args

